export const STROPHEN = [
  {"n":1,"s":"1-die-bruecke","c":"I","t":"Die Brücke","b":"Nicht die Welt begründet den Anschluss – der Anschluss erfindet die Welt, die ihn im Nachhinein notwendig erscheinen lässt.","x":"Jede Theorie beginnt mit einer Brücke. Sie verbindet Begriffe, noch bevor sie weiss, ob auf der anderen Seite überhaupt etwas auf sie wartet. Darin liegt ihre eigentliche Kühnheit. Nicht die Wahrheit ist ihr erster Schritt, sondern die Unterstellung einer Verbindung. Erst wenn spätere Operationen diese Verbindung wieder aufnehmen, erhält sie den Anschein einer notwendigen Ordnung. Was wir Ursprung nennen, ist deshalb meist nichts anderes als der erste geglückte Anschluss. Brücken werden nicht gebaut, weil Ufer existieren; Ufer entstehen, weil Brücken gelernt haben, ihre eigene Richtung zu erinnern.","r":[{"p":"Niklas Luhmann","s":"niklas-luhmann","w":"Soziale Systeme","d":"Soziologie","n":"Operationen gewinnen Zusammenhang erst durch Anschluss."},{"p":"Karen Barad","s":"karen-barad","w":"Meeting the Universe Halfway","d":"Philosophie","n":"Relationen setzen keine bereits fertigen Relata voraus."},{"p":"Mona Hatoum","s":"mona-hatoum","w":"Measures of Distance","d":"Kunst","n":"Nähe und Distanz entstehen in einer vermittelten Beziehung."},{"p":"Franz Kafka","s":"franz-kafka","w":"Die Brücke","d":"Literatur","n":"Die Brücke wird selbst zum prekären Ereignis des Verbindens."}],"v":[3,7,15,17,22,24,25,26,28,37,45]},
  {"n":2,"s":"2-das-ereignis","c":"I","t":"Das Ereignis","b":"Was geschehen ist, ist geschehen; seine Geschichte verändert sich mit jedem Anschluss.","x":"Ein Ereignis findet statt und ist im nächsten Augenblick vorbei. Was geschehen ist, lässt sich nicht nachträglich ungeschehen machen. Offen bleibt dagegen, welchen Platz es in einer Geschichte erhält. Ein späterer Anschluss kann es zum Anfang, Fehler, Zufall oder Wendepunkt machen. Die Vorstellung einer geraden Entwicklung liest eine Richtung in frühere Momente hinein, die damals noch offen war. Jede Gegenwart wählt Spuren aus und ordnet sie neu. Sie verändert damit die Geschichte, die über das Geschehene erzählt werden kann. Gerade weil das Ereignis vergangen ist, steht seine Bedeutung nie ein für alle Mal fest.","r":[{"p":"Barbara Adam","s":"barbara-adam","w":"Time and Social Theory","d":"Soziologie","n":"Soziale Zeit entsteht in Praktiken der Ordnung und Erwartung."},{"p":"Alfred North Whitehead","s":"alfred-north-whitehead","w":"Process and Reality","d":"Philosophie","n":"Wirklichkeit wird als Ereignis- und Prozessgeschehen gedacht."},{"p":"On Kawara","s":"on-kawara","w":"Today Series","d":"Kunst","n":"Das Datum fixiert ein Ereignis, ohne dessen spätere Bedeutung festzulegen."},{"p":"Virginia Woolf","s":"virginia-woolf","w":"Mrs Dalloway","d":"Literatur","n":"Ein Tag wird durch Erinnerung und Gegenwart fortwährend neu geschichtet."}],"v":[6,7,38,43,49]},
  {"n":3,"s":"3-der-anschluss","c":"I","t":"Der Anschluss","b":"Kontinuität ist kein Zustand – sie ist die unwahrscheinlichste aller Operationen.","x":"Die eigentliche Leistung eines Systems besteht nicht darin, etwas hervorzubringen, sondern darin, weiterzumachen. Jede Operation verschwindet im Augenblick ihres Vollzugs. Dauer entsteht deshalb nicht durch Bestand, sondern durch Wiederaufnahme. Was wir Identität nennen, ist nichts anderes als die erfolgreiche Gewohnheit, den nächsten Schritt an den vorherigen anzuschliessen. Jeder misslungene Anschluss eröffnet dagegen eine andere Geschichte. Systeme leben deshalb nicht von Stabilität, sondern von der unwahrscheinlichen Fähigkeit, den eigenen Abbruch immer wieder in Fortsetzung zu verwandeln.","r":[{"p":"Niklas Luhmann","s":"niklas-luhmann","w":"Soziale Systeme","d":"Soziologie","n":"Autopoiesis besteht in der rekursiven Produktion weiterer Operationen."},{"p":"Jacques Derrida","s":"jacques-derrida","w":"La différance","d":"Philosophie","n":"Fortsetzung beruht auf Spur, Wiederholung und Verschiebung."},{"p":"Lygia Clark","s":"lygia-clark","w":"Bichos","d":"Kunst","n":"Form entsteht jeweils neu im Vollzug ihrer nächsten Artikulation."},{"p":"Clarice Lispector","s":"clarice-lispector","w":"A paixão segundo G.H.","d":"Literatur","n":"Erfahrung setzt sich fort, indem ihre bisherige Ordnung zerfällt."}],"v":[1,5,7,11,15,23,24,26,28,33,45,47]},
  {"n":4,"s":"4-der-beobachter","c":"I","t":"Der Beobachter","b":"Der Beobachter kann die Unterscheidung seines gegenwärtigen Beobachtens erst später beobachten.","x":"Beobachten heisst, eine Unterscheidung zu verwenden und eine ihrer Seiten zu bezeichnen. Der Beobachter steht dieser Operation nicht als zusätzliche Instanz gegenüber: Er wird erst durch die Art seines Beobachtens bestimmbar. Während er etwas sieht, kann er die Unterscheidung, mit der er gerade sieht, nicht zugleich als dieselbe Operation beobachten. Eine spätere Beobachtung kann diese Voraussetzung sichtbar machen; sie verwendet dafür wieder eine eigene Unterscheidung. So verschiebt Selbstbeobachtung ihren blinden Fleck, statt ihn ein für alle Mal aufzuheben. Auch der vermeintliche Anfang des Beobachtens erscheint erst aus einer späteren Perspektive als Anfang.","r":[{"p":"Heinz von Foerster","s":"heinz-von-foerster","w":"On Constructing a Reality","d":"Kybernetik","n":"Ein Beobachter lässt sich aus der eigenen Konstruktion von Wirklichkeit nicht herausrechnen; jede spätere Beobachtung bringt erneut eigene Voraussetzungen mit."},{"p":"Donna Haraway","s":"donna-haraway","w":"Situated Knowledges","d":"Philosophie","n":"Jede Beobachtung hat einen situierten Standpunkt und damit Grenzen."},{"p":"Cindy Sherman","s":"cindy-sherman","w":"Untitled Film Stills","d":"Kunst","n":"Beobachtung und beobachtete Identität verschieben sich gegenseitig."},{"p":"Jorge Luis Borges","s":"jorge-luis-borges","w":"Pierre Menard, Autor des Quijote","d":"Literatur","n":"Dasselbe Zeichen wird durch den Ort seiner Beobachtung ein anderes."}],"v":[12,36]},
  {"n":5,"s":"5-der-blinde-fleck","c":"I","t":"Der blinde Fleck","b":"Der blinde Fleck ist nicht das Ende der Erkenntnis – er ist ihr Anfang.","x":"Jede Operation vollzieht sich unter Bedingungen, die sie selbst nicht beobachten kann. Nicht weil ihr Informationen fehlen, sondern weil ihre eigene Form bestimmt, was überhaupt als Information erscheinen darf. Der blinde Fleck ist deshalb kein Defizit des Wissens, sondern seine Voraussetzung. Wer ihn beseitigen wollte, müsste ausserhalb seiner eigenen Operation treten – und würde gerade dadurch eine neue Unterscheidung mit einem neuen blinden Fleck erzeugen. Erkenntnis erweitert ihr Gesichtsfeld nicht, indem sie Blindheit überwindet, sondern indem sie lernt, ihre eigenen Grenzen produktiv zu variieren.","r":[{"p":"Elena Esposito","s":"elena-esposito","w":"Die Beobachtung der Kybernetik","d":"Soziologie","n":"Beobachtung zweiter Ordnung macht die Selektivität des Beobachtens sichtbar."},{"p":"George Spencer-Brown","s":"george-spencer-brown","w":"Laws of Form","d":"Philosophie","n":"Jede Bezeichnung setzt eine unbezeichnete Seite voraus."},{"p":"René Magritte","s":"rene-magritte","w":"La condition humaine","d":"Kunst","n":"Bild und Welt werden durch eine unsichtbare Grenze unterschieden."},{"p":"Clarice Lispector","s":"clarice-lispector","w":"A paixão segundo G.H.","d":"Literatur","n":"Erkenntnis beginnt dort, wo vertraute Unterscheidungen unhaltbar werden."}],"v":[3,8,12,19,36]},
  {"n":6,"s":"6-die-verspaetung","c":"I","t":"Die Verspätung","b":"Gegenwart ist die Kunst, ihre eigene Verspätung zu übersehen.","x":"Jede Gegenwart erscheint sich selbst unmittelbar. Tatsächlich kommt sie immer zu spät. Noch bevor eine Operation sich als gegenwärtig erfährt, ist sie bereits vergangen und kann nur durch weitere Operationen wieder aufgenommen werden. Was wir Präsenz nennen, ist deshalb kein zeitlicher Punkt, sondern eine fortlaufende Rekonstruktion. Gegenwart lebt davon, dass sie ihre eigene Verspätung ununterbrochen vergisst. Gerade diese kleine Verzögerung ermöglicht Erinnerung, Erwartung und Anschluss. Ohne sie gäbe es weder Zeit noch Geschichte, sondern bloss das lautlose Erlöschen isolierter Ereignisse.","r":[{"p":"Barbara Adam","s":"barbara-adam","w":"Time and Social Theory","d":"Soziologie","n":"Gegenwart ist sozial organisiert und nie bloss ein neutraler Zeitpunkt."},{"p":"Edmund Husserl","s":"edmund-husserl","w":"Vorlesungen zur Phänomenologie des inneren Zeitbewusstseins","d":"Philosophie","n":"Retention und Protention strukturieren das erlebte Jetzt."},{"p":"Hito Steyerl","s":"hito-steyerl","w":"In Free Fall","d":"Kunst","n":"Gegenwart erscheint als instabiler Zustand fortgesetzter Verschiebung."},{"p":"Marcel Proust","s":"marcel-proust","w":"À la recherche du temps perdu","d":"Literatur","n":"Vergangenheit wird erst in späteren Gegenwarten wirksam."}],"v":[2,10,35,37,38]},
  {"n":7,"s":"7-die-zeit","c":"I","t":"Die Zeit","b":"Zeit ist die Bedingung, dass auf eine Operation auch anderes folgen kann als ihre Wiederholung.","x":"Zeit trägt Ereignisse nicht wie ein Strom von einem Ort zum anderen. Eine Operation endet mit ihrem Vollzug; was geschehen ist, lässt sich nicht wiederholen, als wäre es noch Gegenwart. Zugleich kann eine spätere Operation daran anschliessen und unter veränderten Bedingungen anderes daraus machen. Hier liegt die Spannung von Vergangenheit und Zukunft: Das Geschehene ist festgelegt, seine möglichen Fortsetzungen sind es nicht. Dauer entsteht, wenn Anschlüsse wieder möglich werden; ein Bruch verändert ihre Bedingungen. Zeit bezeichnet in dieser Strophe die Differenz, die jede Wiederaufnahme mitführt: Das Nächste kann anschliessen, ohne auf dieselbe Weise weiterzugehen.","r":[{"p":"Niklas Luhmann","s":"niklas-luhmann","w":"Soziale Systeme; Die Zukunft kann nicht beginnen","d":"Soziologie","n":"Zeit ordnet Aktualität und Nichtaktualität innerhalb gegenwärtiger Operationen."},{"p":"Isabelle Stengers","s":"isabelle-stengers","w":"Thinking with Whitehead","d":"Philosophie","n":"Zeitlichkeit wird aus Werden und irreversiblen Beziehungen gedacht."},{"p":"Christian Marclay","s":"christian-marclay","w":"The Clock","d":"Kunst","n":"Chronologische Zeit wird aus tausenden heterogenen Filmgegenwarten montiert."},{"p":"Virginia Woolf","s":"virginia-woolf","w":"To the Lighthouse","d":"Literatur","n":"Dauer entsteht in der Verschiebung zwischen Ereignis, Erinnerung und Abwesenheit."}],"v":[1,2,3,15,24,26,28,41,43,45]},
  {"n":8,"s":"8-der-speicher","c":"II","t":"Der Speicher","b":"Speicherung hält etwas verfügbar; Wiederaufnahme gibt ihm eine neue Gegenwart.","x":"Eine Bibliothek bewahrt Bücher auf, eine Festplatte Daten. Solche Speicher halten materielle Zustände verfügbar und schützen sie gegen rasches Verschwinden. Damit ist noch nicht erklärt, weshalb etwas Jahre später Bedeutung gewinnt. Ein aufgefundenes Buch muss gelesen, ein Datensatz ausgewählt, ein Fundstück in eine Frage eingebracht werden. Speicherung schafft eine mögliche spätere Begegnung; Erinnerung beginnt mit deren gegenwärtigem Vollzug. Beides braucht einander oft, fällt aber nicht zusammen. Selbst ein vollständig erhaltenes Dokument kann unlesbar werden, wenn seine Sprache und sein Zusammenhang verloren gehen. Der Speicher sichert Verfügbarkeit; über die nächste Verwendung entscheidet er nicht.","r":[{"p":"Elena Esposito","s":"elena-esposito","w":"Soziales Vergessen","d":"Soziologie","n":"Gedächtnis ist Selektionsleistung und nicht bloss Ablage."},{"p":"Henri Bergson","s":"henri-bergson","w":"Matière et mémoire","d":"Philosophie","n":"Gedächtnis lässt sich nicht auf materielle Speicherung reduzieren."},{"p":"Christian Boltanski","s":"christian-boltanski","w":"Réserve","d":"Kunst","n":"Aufbewahrung produziert eine Gegenwart der Abwesenheit."},{"p":"Ursula K. Le Guin","s":"ursula-k-le-guin","w":"Always Coming Home","d":"Literatur","n":"Archive werden als spätere Konstruktionen kultureller Wiederverwendung inszeniert."}],"v":[5,12,17,19,36,47]},
  {"n":9,"s":"9-das-gedaechtnis","c":"II","t":"Das Gedächtnis","b":"Gedächtnis macht Vergangenes in veränderten Praktiken erneut wirksam.","x":"Gedächtnis zeigt sich, wenn Vergangenes in einer gegenwärtigen Praxis erneut wirksam wird. Eine Erzählung ruft frühere Ereignisse anders auf als eine Geste, ein geübter Handgriff oder ein Ritual. Solche Wiederaufnahmen besitzen Geschichte; sie vollziehen sich unter Bedingungen, die sich verändert haben. Auch der Körper trägt Gewohnheiten und Fähigkeiten, ohne dafür jederzeit ein Bild des Vergangenen bereitzuhalten. Deshalb lässt sich Gedächtnis weder auf Ablage noch auf bewusste Erinnerung reduzieren. Es ist an Materialien, Körper und soziale Formen gebunden und bleibt zugleich eine gegenwärtige Leistung. Was wiederkehrt, kehrt in einer neuen Situation wieder.","r":[{"p":"Paul Connerton","s":"paul-connerton","w":"How Societies Remember","d":"Soziologie","n":"Körperliche Praktiken und Rituale geben gesellschaftliche Erinnerung weiter, ohne dass sie auf bewusste Repräsentation reduziert werden kann."},{"p":"Gilles Deleuze","s":"gilles-deleuze","w":"Différence et répétition","d":"Philosophie","n":"Wiederholung erzeugt Differenz statt identische Rückkehr."},{"p":"Doris Salcedo","s":"doris-salcedo","w":"Atrabiliarios","d":"Kunst","n":"Spuren des Vergangenen bleiben wirksam, ohne Gegenwart zu werden."},{"p":"Toni Morrison","s":"toni-morrison","w":"Beloved","d":"Literatur","n":"Vergangenheit kehrt transformiert und handlungswirksam in die Gegenwart zurück."}],"v":[12,27,30,36,46]},
  {"n":10,"s":"10-die-erinnerung","c":"II","t":"Die Erinnerung","b":"Erinnerung gibt Geschehenem eine gegenwärtige, überprüfbare Gestalt.","x":"Erinnerung geschieht in der Gegenwart. Wenn eine Erfahrung erzählt, ein Bild betrachtet oder ein früherer Satz erneut gelesen wird, erhält Vergangenes eine heutige Gestalt. Diese Gestalt kann sich ändern, ohne dass das vergangene Ereignis selbst nachträglich ein anderes wird. Erinnerungen greifen auf Spuren zurück, ergänzen Lücken und sind an Erwartungen gebunden. Sie können einander widersprechen; Gegenstände und Zeugnisse setzen ihren Deutungen zugleich Grenzen. Das Erinnerte ist deshalb weder eine unveränderte Kopie noch eine freie Erfindung. Erinnerung stellt eine Beziehung zu dem her, was geschehen ist und nur aus späteren Gegenwarten erneut befragt werden kann.","r":[{"p":"Maurice Halbwachs","s":"maurice-halbwachs","w":"Les cadres sociaux de la mémoire","d":"Soziologie","n":"Erinnerung wird in sozialen Bezugsrahmen rekonstruiert."},{"p":"Hannah Arendt","s":"hannah-arendt","w":"Between Past and Future","d":"Philosophie","n":"Vergangenheit gewinnt Bedeutung aus der gegenwärtigen Zwischenstellung."},{"p":"Sophie Calle","s":"sophie-calle","w":"Douleur exquise","d":"Kunst","n":"Wiederholtes Erzählen verwandelt die erinnerte Erfahrung."},{"p":"Marcel Proust","s":"marcel-proust","w":"À la recherche du temps perdu","d":"Literatur","n":"Erinnerung erzeugt eine neue Gegenwart des Vergangenen."}],"v":[6,14,15,36,46]},
  {"n":11,"s":"11-die-spur","c":"II","t":"Die Spur","b":"Die Spur hält eine vergangene Wirkung materiell fest, ohne ihre Bedeutung festzulegen.","x":"Ein Fussabdruck im Sand, ein vergilbtes Foto oder eine Falte im Papier erinnert sich an nichts. Doch jede Spur besitzt eine materielle Beschaffenheit, die spätere Deutungen ermöglicht und begrenzt. Der Abdruck gibt nicht von selbst Auskunft darüber, wer vorbeikam; ebenso wenig lässt sich ihm jede beliebige Bewegung zuschreiben. Ob eine Spur zum Beweis, zur Erzählung, zum Kunstwerk oder zum Abfall wird, entscheidet sich in einer späteren Praxis. Ihr Material bleibt dabei eigensinnig. Die Spur verbindet ein vergangenes Geschehen mit möglichen gegenwärtigen Fragen, ohne die Antwort bereits in sich zu tragen.","r":[{"p":"Aleida Assmann","s":"aleida-assmann","w":"Erinnerungsräume","d":"Soziologie","n":"Materielle Spuren benötigen kulturelle Formen ihrer Reaktivierung."},{"p":"Jacques Derrida","s":"jacques-derrida","w":"De la grammatologie","d":"Philosophie","n":"Die Spur unterläuft die Vorstellung reiner Präsenz."},{"p":"Rachel Whiteread","s":"rachel-whiteread","w":"House","d":"Kunst","n":"Abwesenheit wird als materiell lesbare Spur geformt."},{"p":"W. G. Sebald","s":"w-g-sebald","w":"Austerlitz","d":"Literatur","n":"Bilder und Orte werden zu prekären Auslösern später Erinnerung."}],"v":[3,13,14]},
  {"n":12,"s":"12-das-vergessen","c":"II","t":"Das Vergessen","b":"Vergessen verändert, was für wen noch erreichbar bleibt.","x":"Vergessen hat mehrere Formen. Ein Dokument kann vernichtet werden, eine Fähigkeit verkümmern, ein Name aus öffentlichen Aufzeichnungen verschwinden. In anderen Fällen bleibt eine Spur vorhanden, aber die Wege zu ihr werden unbrauchbar oder unwahrscheinlich. Gesellschaftliches Vergessen ordnet so mit, was erneut erzählt, geprüft oder erwartet werden kann. Diese Selektion entlastet; sie kann aber auch Menschen und Ereignisse aus dem erreichbaren Gedächtnis drängen. Vergessen ist daher weder bloss ein Mangel noch immer eine schöpferische Leistung. Seine Folgen hängen daran, was verloren geht, für wen etwas unzugänglich wird und wer darüber entscheiden kann.","r":[{"p":"Elena Esposito","s":"elena-esposito","w":"Soziales Vergessen","d":"Soziologie","n":"Vergessen ist eine positive Bedingung selektiver Erinnerung."},{"p":"Friedrich Nietzsche","s":"friedrich-nietzsche","w":"Zur Genealogie der Moral","d":"Philosophie","n":"Aktives Vergessen schafft Spielraum für Gegenwart und Handlung."},{"p":"Doris Salcedo","s":"doris-salcedo","w":"Shibboleth","d":"Kunst","n":"Die geschlossene Spur bleibt als nicht beseitigte Differenz sichtbar."},{"p":"Jorge Luis Borges","s":"jorge-luis-borges","w":"Funes el memorioso","d":"Literatur","n":"Vollständige Erinnerung erscheint als Unfähigkeit zur Abstraktion."}],"v":[4,5,8,9,19,36,46]},
  {"n":13,"s":"13-das-archiv","c":"II","t":"Das Archiv","b":"Das Archiv bewahrt und ordnet, was künftig wiedergefunden werden kann.","x":"Ein Archiv bewahrt Dokumente und Gegenstände auf. Es ordnet sie zugleich nach Regeln, die bestimmen, was aufgenommen, beschrieben und wiedergefunden werden kann. Diese Regeln schaffen künftige Möglichkeiten und begrenzen sie: Ohne Verzeichnung bleibt selbst Erhaltenes schwer erreichbar; was nie gesammelt wurde, kann nicht einfach zurückgerufen werden. Eine Akte wird erst durch Fragen, Verfahren und Widerspruch zum Beweis. Archive erzählen deshalb nicht schon selbst Geschichte. Sie stellen Material bereit und prägen, welche Geschichten daraus werden können. Ihre Leistung liegt in der Verbindung von Bewahrung, Auswahl und Zugang – und damit auch in der Macht, diese Bedingungen zu setzen.","r":[{"p":"Aleida Assmann","s":"aleida-assmann","w":"Erinnerungsräume","d":"Soziologie","n":"Archive organisieren kulturelle Verfügbarkeit jenseits aktueller Erinnerung."},{"p":"Michel Foucault","s":"michel-foucault","w":"L’archéologie du savoir","d":"Philosophie","n":"Sein Begriff des Archivs meint Regeln des Sagbaren und der Wiederholbarkeit; er erweitert und irritiert den hier behandelten institutionellen Archivbegriff."},{"p":"Walid Raad","s":"walid-raad","w":"The Atlas Group","d":"Kunst","n":"Archivform und Dokumentstatus werden künstlerisch destabilisiert."},{"p":"Anne Carson","s":"anne-carson","w":"Nox","d":"Literatur","n":"Das private Archiv bleibt fragmentarisch und erzeugt Bedeutung erst im Arrangement."}],"v":[11]},
  {"n":14,"s":"14-die-geschichte","c":"II","t":"Die Geschichte","b":"Geschichte deutet Vergangenes neu und bleibt an seine Spuren gebunden.","x":"Vergangene Ereignisse sind geschehen, auch wenn niemand mehr von ihnen erzählt. Geschichte entsteht, wenn Gesellschaft ihre Spuren, Zeugnisse und Überlieferungen ordnet, bestreitet und erneut deutet. Mit jeder Gegenwart können andere Fragen und bisher übersehene Dokumente wichtig werden. Das verändert die erzählbare Geschichte; das Geschehene wird dadurch nicht beliebig. Eine Behauptung muss sich an den verfügbaren Spuren, an anderen Berichten und an ihren Lücken bewähren. Geschichte ist weder identisch mit dem Archiv noch die blosse Summe von Erinnerungen. Sie ist eine streitige, gegenwärtige Arbeit an einer Vergangenheit, die sich nicht in ihrer heutigen Verwendung erschöpft.","r":[{"p":"Maurice Halbwachs","s":"maurice-halbwachs","w":"La mémoire collective","d":"Soziologie","n":"Vergangenheit wird in wechselnden sozialen Rahmen rekonstruiert."},{"p":"Hannah Arendt","s":"hannah-arendt","w":"Between Past and Future","d":"Philosophie","n":"Geschichte steht in einer Gegenwart zwischen Herkunft und Möglichkeit."},{"p":"Susan Hiller","s":"susan-hiller","w":"The J. Street Project","d":"Kunst","n":"Dokumentation verändert, was als erinnerbare Geschichte sichtbar bleibt."},{"p":"W. G. Sebald","s":"w-g-sebald","w":"Die Ringe des Saturn","d":"Literatur","n":"Geschichte entsteht aus Montage, Spur und gegenwärtiger Wanderung."}],"v":[10,11,46]},
  {"n":15,"s":"15-die-adresse","c":"III","t":"Die Adresse","b":"Die Adresse macht soziale Zurechnung über Abwesenheit hinweg möglich.","x":"Kommunikation braucht Adressen, an die Aussagen, Erwartungen und Antworten zugerechnet werden können. Ein Name, eine Organisation oder ein technisches Konto macht jemanden oder etwas auch dann erreichbar, wenn sein Träger abwesend ist. Solche Adressen entstehen und verändern sich durch wiederholte Bezugnahmen. Sie sind jedoch nicht der Ursprung jedes körperlichen oder psychischen Geschehens. Ihr Bereich ist die soziale Zurechnung: Wer wird als dieselbe Stelle angesprochen, wer kann antworten, wer bleibt verantwortlich? Eine Adresse hält diese Möglichkeiten über einzelne Situationen hinweg offen. Wie jemand adressiert wird, beeinflusst seine soziale Identität, ohne mit seinem Leben zusammenzufallen.","r":[{"p":"Niklas Luhmann","s":"niklas-luhmann","w":"Die Form „Person“","d":"Soziologie","n":"Kommunikation bündelt Erwartungen an wiedererkennbare soziale Adressen."},{"p":"Adriana Cavarero","s":"adriana-cavarero","w":"Relating Narratives","d":"Philosophie","n":"Das Wer einer Person entsteht relational und narrativ."},{"p":"Sophie Calle","s":"sophie-calle","w":"Suite vénitienne","d":"Kunst","n":"Eine Person erscheint über adressierbare Spuren und Beobachtungen."},{"p":"Italo Calvino","s":"italo-calvino","w":"Le città invisibili","d":"Literatur","n":"Namen halten Orte zusammen, deren Identität sich im Erzählen verändert."}],"v":[1,3,7,10,16,24,26,28,33,36,45]},
  {"n":16,"s":"16-der-name","c":"III","t":"Der Name","b":"Der Name macht Abwesenheit adressierbar.","x":"Ein Name sagt nicht, wer jemand ist. Er sorgt dafür, dass dieselbe Adresse auch dann wiederaufgerufen werden kann, wenn ihr Träger abwesend, verändert oder widersprüchlich geworden ist. Namen verdichten vergangene Adressierungen zu einer Form, an die Erwartungen, Geschichten und Verantwortungen anschliessen. Darin liegt ihre Macht und ihre Gewalt. Wer einen Namen erhält, wird sozial auffindbar, aber auch festgelegt; wer umbenannt wird, verliert nicht nur ein Wort, sondern eine bereits organisierte Zukunft möglicher Zuschreibungen. Der Name gehört deshalb niemandem ganz. Er zirkuliert zwischen Eigengebrauch und Fremdverwendung und hält eine soziale Einheit dort zusammen, wo keine Identität sich selbst genügt.","r":[{"p":"Pierre Bourdieu","s":"pierre-bourdieu","w":"Language and Symbolic Power","d":"Soziologie","n":"Benennung wirkt als soziale Einsetzung und Zurechnung."},{"p":"Adriana Cavarero","s":"adriana-cavarero","w":"Relating Narratives","d":"Philosophie","n":"Der Eigenname hält die Einzigartigkeit einer adressierbaren Person offen."},{"p":"Lubaina Himid","s":"lubaina-himid","w":"Naming the Money","d":"Kunst","n":"Benennung gibt anonymisierten Figuren Geschichte und soziale Adresse zurück."},{"p":"Paul Auster","s":"paul-auster","w":"City of Glass","d":"Literatur","n":"Namen, Rollen und Identitäten geraten in ein Spiel wechselseitiger Ersetzung."}],"v":[15,48]},
  {"n":17,"s":"17-die-person","c":"III","t":"Die Person","b":"Die Person ist das Gedächtnis einer Adresse.","x":"Eine Person ist nicht der Mensch, den sie bezeichnet. Sie ist die Form, in der Kommunikation zahlreiche Erwartungen auf eine wiedererkennbare Adresse bündelt. Wer als freundlich, unzuverlässig, krank, zuständig oder gefährlich gilt, wird nicht vollständig beschrieben, sondern für weitere Anschlüsse vorbereitet. Darin liegt die Entlastung der Person: Niemand muss in jeder Begegnung neu erfunden werden. Darin liegt zugleich ihre Härte: Was einmal zugerechnet wurde, kehrt als Erwartung zurück und begrenzt, was künftig noch glaubhaft erscheinen kann. Personen bestehen deshalb weder aus Eigenschaften noch aus Innerlichkeit. Sie entstehen, indem Adressierungen sich verdichten und ihre eigene Wiederholung erwarten.","r":[{"p":"Cornelia Bohn","s":"cornelia-bohn","w":"Inklusion, Exklusion und die Person","d":"Soziologie","n":"Personen fungieren als soziale Formen der Zurechnung."},{"p":"Judith Butler","s":"judith-butler","w":"Giving an Account of Oneself","d":"Philosophie","n":"Selbstbeschreibung bleibt an soziale Normen und Adressierungen gebunden."},{"p":"Christian Boltanski","s":"christian-boltanski","w":"Les Suisses morts","d":"Kunst","n":"Personen werden durch Namen, Bilder und archivierte Spuren sozial präsent."},{"p":"Franz Kafka","s":"franz-kafka","w":"Der Prozess","d":"Literatur","n":"Eine Person wird von Zuschreibungen bestimmt, deren Ordnung sie nicht kontrolliert."}],"v":[1,8,18,22,25,45]},
  {"n":18,"s":"18-die-rolle","c":"III","t":"Die Rolle","b":"Die Rolle macht Erwartungen von Personen unabhängig.","x":"Eine Rolle ist keine Maske, hinter der sich die wirkliche Person verbirgt. Sie ist eine Ordnung von Erwartungen, die bereits besteht, bevor jemand sie übernimmt. Lehrerin, Mutter, Patient, Künstler oder Richterin bezeichnen keine Eigenschaften, sondern Positionen, von denen aus bestimmte Handlungen wahrscheinlich und andere erklärungsbedürftig werden. Rollen entlasten Personen, weil sie nicht ihre ganze Individualität in jede Situation einbringen müssen. Zugleich setzen sie Grenzen: Wer eine Rolle übernimmt, wird an Erwartungen gemessen, die nicht mit ihm entstanden sind. So macht die Rolle soziale Beziehungen wiederholbar, indem sie Personen austauschbar macht, ohne sie vollständig zu ersetzen.","r":[{"p":"Erving Goffman","s":"erving-goffman","w":"The Presentation of Self in Everyday Life","d":"Soziologie","n":"Rollen strukturieren Situationen, Erwartungen und Selbstdarstellungen."},{"p":"Judith Butler","s":"judith-butler","w":"Gender Trouble","d":"Philosophie","n":"Wiederholte Performanz stabilisiert soziale Identitäten ohne festen Kern."},{"p":"Gillian Wearing","s":"gillian-wearing","w":"Album","d":"Kunst","n":"Rolle, Gesicht und biografische Zuschreibung werden gegeneinander verschoben."},{"p":"Luigi Pirandello","s":"luigi-pirandello","w":"Sei personaggi in cerca d’autore","d":"Literatur","n":"Figur, Rolle und Person lösen sich voneinander."}],"v":[17,43,45]},
  {"n":19,"s":"19-die-erwartung","c":"III","t":"Die Erwartung","b":"Erwartungen ordnen, was an einer Adresse künftig überraschen kann.","x":"Erwartungen sagen nicht sicher voraus, was eintreten wird. Sie bestimmen, was als passend, abweichend oder überraschend gelten kann. Ein Name, eine Rolle und eine vertraute Beziehung bringen solche Erwartungen mit; dadurch wird Zukunft schon gegenwärtig geordnet. Enttäuschungen können eine Erwartung verändern. Sie können aber auch zu ihrer Bekräftigung führen, wenn die Abweichung als Ausnahme behandelt oder einer Person zugeschrieben wird. Gerade darin liegt ihre soziale Beharrlichkeit. Eine Erwartung verbindet eine Adresse mit möglichen nächsten Ereignissen und legt zugleich fest, wie mit dem Unerwarteten umgegangen werden kann.","r":[{"p":"Elena Esposito","s":"elena-esposito","w":"Die Fiktion der wahrscheinlichen Realität","d":"Soziologie","n":"Erwartungen strukturieren Ungewissheit, ohne Zukunft festzulegen."},{"p":"Reinhart Koselleck","s":"reinhart-koselleck","w":"Vergangene Zukunft","d":"Philosophie","n":"Erfahrungsraum und Erwartungshorizont ordnen historische Zeit."},{"p":"Yoko Ono","s":"yoko-ono","w":"Grapefruit","d":"Kunst","n":"Anweisungen erzeugen Erwartungen, deren Ausführung offen bleibt."},{"p":"Samuel Beckett","s":"samuel-beckett","w":"En attendant Godot","d":"Literatur","n":"Erwartung organisiert Gegenwart, ohne ihre Erfüllung garantieren zu können."}],"v":[5,8,12,24,36,44,46]},
  {"n":20,"s":"20-die-verantwortung","c":"III","t":"Die Verantwortung","b":"Verantwortung bindet Folgen an eine Adresse.","x":"Verantwortung entsteht nicht im Inneren einer Person. Sie entsteht, wenn Kommunikation eine Handlung und ihre Folgen einer Adresse zurechnet. Wer verantwortlich gemacht wird, bleibt für etwas erreichbar, das bereits geschehen ist und dennoch weitere Antworten verlangt. Darin verbindet Verantwortung Vergangenheit und Zukunft: Sie hält eine Adresse über wechselnde Situationen hinweg fest und erwartet von ihr Rechtfertigung, Wiedergutmachung oder Veränderung. Diese Bindung kann Handlung ermöglichen, aber auch Schuld verteilen, Zuständigkeiten verschieben und Macht verdecken. Verantwortung bezeichnet deshalb keine moralische Eigenschaft. Sie ist das soziale Verfahren, mit dem Folgen einen antwortfähigen Ort erhalten.","r":[{"p":"Marilyn Strathern (Hg.)","s":"marilyn-strathern-hg","w":"Audit Cultures","d":"Soziologie","n":"Zurechnung und Rechenschaft organisieren institutionelle Verantwortlichkeit."},{"p":"Emmanuel Levinas","s":"emmanuel-levinas","w":"Autrement qu’être","d":"Philosophie","n":"Verantwortung beginnt in der Ansprechbarkeit durch den Anderen."},{"p":"Teresa Margolles","s":"teresa-margolles","w":"¿De qué otra cosa podríamos hablar?","d":"Kunst","n":"Folgen gesellschaftlicher Gewalt werden an Wahrnehmung und Öffentlichkeit adressiert."},{"p":"J. M. Coetzee","s":"j-m-coetzee","w":"Disgrace","d":"Literatur","n":"Verantwortung bleibt strittig zwischen Schuld, Antwort und sozialer Zurechnung."}],"v":[]},
  {"n":21,"s":"21-die-anerkennung","c":"III","t":"Die Anerkennung","b":"Anerkennung verleiht einer Adresse soziale Geltung.","x":"Anerkennung entdeckt keine bereits vorhandene Identität. Sie bestätigt eine Adresse als gültigen Ort weiterer Kommunikation. Wer anerkannt wird, darf sprechen, handeln, erinnern und Ansprüche stellen, ohne bei jeder Begegnung die eigene Zugehörigkeit neu beweisen zu müssen. Doch Anerkennung ist niemals vollständig. Sie erfasst eine Person nur in Formen, die sozial lesbar sind, und kann gerade dadurch anderes an ihr übersehen oder ausschliessen. Auch Verkennung hält Adressen wirksam, indem sie ihnen fremde Eigenschaften zuschreibt. Anerkennung ist deshalb kein Besitz, sondern ein fortlaufender sozialer Vollzug, in dem sich entscheidet, wer als wer erscheinen kann.","r":[{"p":"Michèle Lamont","s":"michele-lamont","w":"The Dignity of Working Men","d":"Soziologie","n":"Anerkennung hängt an sozialen Grenzziehungen und Bewertungsordnungen."},{"p":"Axel Honneth","s":"axel-honneth","w":"Kampf um Anerkennung","d":"Philosophie","n":"Anerkennung wird als Bedingung sozialer Selbstbeziehung gefasst."},{"p":"Kerry James Marshall","s":"kerry-james-marshall","w":"Mastry","d":"Kunst","n":"Sichtbarkeit und kunsthistorische Anerkennung werden neu verteilt."},{"p":"Bernardine Evaristo","s":"bernardine-evaristo","w":"Girl, Woman, Other","d":"Literatur","n":"Identitäten werden durch überlagerte Anerkennungs- und Verkennungsverhältnisse erzählt."}],"v":[]},
  {"n":22,"s":"22-die-grenze","c":"IV","t":"Die Grenze","b":"Nur was getrennt bleibt, kann sich berühren.","x":"Eine Grenze liegt nicht zwischen bereits fertigen Systemen. Sie entsteht mit jeder Operation, die etwas fortsetzt und anderes ausschliesst. Erst diese Unterscheidung erzeugt ein Innen, dem weitere Operationen zugerechnet werden können, und ein Aussen, das nicht verschwindet, sondern als Umwelt wirksam bleibt. Grenzen verhindern deshalb Beziehung nicht; sie machen sie möglich. Nur was sich nicht ineinander auflöst, kann sich berühren, irritieren oder koppeln. Die Grenze ist keine Mauer, sondern eine fortlaufend erneuerte Form, an der Eigenes und Fremdes zugleich entstehen. Wo sie fällt, beginnt nicht Einheit, sondern der Verlust jeder unterscheidbaren Beziehung.","r":[{"p":"Susan Leigh Star","s":"susan-leigh-star","w":"Ecologies of Knowledge","d":"Soziologie","n":"Grenzobjekte koordinieren verschiedene soziale Welten ohne deren Verschmelzung."},{"p":"Georg Simmel","s":"georg-simmel","w":"Brücke und Tür","d":"Philosophie","n":"Grenzen und Verbindungen werden als wechselseitig erzeugte Formen gedacht."},{"p":"Mona Hatoum","s":"mona-hatoum","w":"Homebound","d":"Kunst","n":"Nähe wird durch Barriere, Strom und Unzugänglichkeit zugleich erzeugt."},{"p":"Franz Kafka","s":"franz-kafka","w":"Vor dem Gesetz","d":"Literatur","n":"Die Grenze existiert als relationale Ordnung von Zugang und Aufschub."}],"v":[1,17,25,27,45]},
  {"n":23,"s":"23-die-beruehrung","c":"IV","t":"Die Berührung","b":"Berührung ist die Grenze in Ereignisform.","x":"Berührung hebt keine Grenze auf. Sie ist der Augenblick, in dem zwei getrennte Ordnungen aneinander Folgen erzeugen. Eine Hand spürt die andere nicht so, wie diese sich selbst spürt; jede Seite erzeugt aus dem Kontakt ein eigenes Ereignis. Gerade deshalb kann Berührung weder Besitz noch Verschmelzung sein. Sie verändert, ohne etwas unverändert zu übertragen. In ihr wird die Grenze empfindlich: Druck, Wärme, Widerstand und Nähe erscheinen nur, weil Körper einander nicht werden. Auch soziale Berührung folgt dieser Logik. Sie lässt Fremdes wirksam werden, ohne es in Eigenes zu verwandeln. Wo Berührung gelingt, bleibt Differenz nicht trotz, sondern durch Nähe erhalten.","r":[{"p":"Eva Illouz","s":"eva-illouz","w":"Cold Intimacies","d":"Soziologie","n":"Nähe ist sozial geformt und an Kommunikationsordnungen gebunden."},{"p":"Jean-Luc Nancy","s":"jean-luc-nancy","w":"Corpus","d":"Philosophie","n":"Körperlichkeit erscheint als Mitsein an Grenzen und Oberflächen."},{"p":"Lygia Clark","s":"lygia-clark","w":"Bichos","d":"Kunst","n":"Berührung verändert die Form, ohne Werk und Betrachter zu vereinigen."},{"p":"Ocean Vuong","s":"ocean-vuong","w":"On Earth We’re Briefly Gorgeous","d":"Literatur","n":"Körperliche Nähe bleibt von Differenz, Erinnerung und Verletzlichkeit durchzogen."}],"v":[3,33,47]},
  {"n":24,"s":"24-die-irritation","c":"IV","t":"Die Irritation","b":"Irritation ist Fremdwirkung in Eigenform.","x":"Eine Irritation dringt nicht von aussen in ein System ein. Sie entsteht, wenn eine fremde Veränderung innerhalb eigener Unterscheidungen Folgen auslöst. Dasselbe Geräusch kann erschrecken, beruhigen oder unbemerkt bleiben; nicht der Reiz bestimmt die Reaktion, sondern die Ordnung, die ihn als Abweichung verarbeitet. Irritation beweist daher weder Offenheit noch Geschlossenheit allein. Sie bezeichnet die paradoxe Stelle, an der ein System von etwas abhängt, das es nicht übernehmen kann. Fremdes wird wirksam, indem es seine Fremdheit verliert und als eigene Differenz fortgesetzt wird. Koppelung beginnt dort, wo solche Irritationen wieder erwartbar werden.","r":[{"p":"Niklas Luhmann","s":"niklas-luhmann","w":"Die Gesellschaft der Gesellschaft","d":"Soziologie","n":"Irritation ist systemeigene Verarbeitung umweltbezogener Differenzen."},{"p":"Isabelle Stengers","s":"isabelle-stengers","w":"Thinking with Whitehead","d":"Philosophie","n":"Beziehungen werden über wechselseitige Bedingungen des Werdens gedacht."},{"p":"Ann Veronica Janssens","s":"ann-veronica-janssens","w":"Blue, Red and Yellow","d":"Kunst","n":"Wahrnehmung wird durch eine Umwelt irritiert, die keine stabile Orientierung gewährt."},{"p":"Samuel Beckett","s":"samuel-beckett","w":"The Unnamable","d":"Literatur","n":"Störung wird zur Form einer Rede, die ihren eigenen Anschluss nicht sichern kann."}],"v":[1,3,7,15,19,26,28,45,46]},
  {"n":25,"s":"25-der-koerper","c":"IV","t":"Der Körper","b":"Der Körper verwandelt Fremdwirkung in Empfindlichkeit.","x":"Der Körper ist keine Brücke, über die Welt unverändert in das Bewusstsein gelangt. Er ist eine Membran, die nichts wirksam werden lässt, ohne es zu verwandeln. Licht, Druck, Temperatur oder ein fremder Blick werden nicht übernommen, sondern in Empfindungen, Bewegungen, Spannungen und Bereitschaften übersetzt. Auch das Bewusstsein verfügt nicht über den Körper, als wäre er sein Besitz. Es begegnet ihm als Schmerz, Lust, Erschöpfung oder Unruhe – als einer Nähe, die niemals vollständig durchsichtig wird. Kommunikation kann diese Zustände benennen, beobachten und adressieren, aber weder den Schmerz noch die Wahrnehmung eines anderen übernehmen. Im Körper wird Umwelt empfindlich, ohne aufzuhören, Umwelt zu sein. Er koppelt, indem er trennt, und verbindet, indem er jede Wirkung in eine eigene Form zwingt.","r":[{"p":"Annemarie Mol","s":"annemarie-mol","w":"The Body Multiple","d":"Soziologie","n":"Körper entstehen in unterschiedlichen Praktiken als verschiedene, gekoppelte Wirklichkeiten."},{"p":"Maurice Merleau-Ponty","s":"maurice-merleau-ponty","w":"Phénoménologie de la perception","d":"Philosophie","n":"Leiblichkeit ist Bedingung eines präreflexiven Weltbezugs."},{"p":"Ana Mendieta","s":"ana-mendieta","w":"Silueta Series","d":"Kunst","n":"Körper und Umgebung schreiben sich ineinander ein, ohne identisch zu werden."},{"p":"Franz Kafka","s":"franz-kafka","w":"Die Verwandlung","d":"Literatur","n":"Der Körper verändert die sozialen Anschlüsse einer Person radikal."}],"v":[1,17,22,26,29]},
  {"n":26,"s":"26-die-wahrnehmung","c":"IV","t":"Die Wahrnehmung","b":"Wahrnehmung lässt die Grenze zwischen Körper und Bewusstsein fraglich werden.","x":"Wahrnehmung macht eine theoretische Grenze spürbar. Bei Luhmann ist sie eine psychische Operation: Das Bewusstsein sieht und hört, auch wenn es darüber nicht nachdenkt. Der Körper ermöglicht und irritiert diesen Vollzug, lässt sich aber nicht einfach mit dem Bewusstsein gleichsetzen. Von Merleau-Pontys Phänomenologie her lässt sich eine andere Frage stellen: Ist der Leib der Wahrnehmung überhaupt als Umwelt gegenüberzustellen, wenn er bereits einen präreflexiven Weltbezug vollzieht? Diese Gegenüberstellung konstruiert die Strophe; sie ist keine direkte Auseinandersetzung der beiden Autoren. Gerade ihre Verschiedenheit zeigt, wie viel davon abhängt, wo die Grenze zwischen Körper und Bewusstsein gezogen wird.","r":[{"p":"Niklas Luhmann","s":"niklas-luhmann","w":"Soziale Systeme; Die Kunst der Gesellschaft","d":"Soziologie","n":"Wahrnehmung bleibt psychische Operation und kann Kommunikation nur irritieren."},{"p":"Maurice Merleau-Ponty","s":"maurice-merleau-ponty","w":"Phénoménologie de la perception","d":"Philosophie","n":"Wahrnehmung ist leiblicher Weltbezug vor reflexiver Objektivierung."},{"p":"Ann Veronica Janssens","s":"ann-veronica-janssens","w":"immersive Licht- und Nebelarbeiten","d":"Kunst","n":"Wahrnehmungsbedingungen selbst werden zum Gegenstand der Erfahrung."},{"p":"Olga Tokarczuk","s":"olga-tokarczuk","w":"Bieguni / Unrast","d":"Literatur","n":"Körper, Bewegung und Wahrnehmung erscheinen als unstabile Ordnungen von Nähe."}],"v":[1,3,7,15,24,25,28,45]},
  {"n":27,"s":"27-die-uebersetzung","c":"IV","t":"Die Übersetzung","b":"Übersetzung ist Wiederholung ohne Identität.","x":"Übersetzung überträgt nichts unverändert von einer Ordnung in eine andere. Wahrnehmung wird nicht zu Sprache, Schmerz nicht zur Mitteilung und ein Gedanke nicht zur Kommunikation. Jede Seite erzeugt aus dem, was sie erreicht, eine eigene Form. Darin liegt der Verlust jeder Übersetzung – und zugleich ihre Möglichkeit: Nur weil Gleichheit unerreichbar ist, kann etwas unter veränderten Bedingungen fortgesetzt werden. Darin berührt sich Übersetzung mit Deleuzes Begriff der Wiederholung, die kein Identisches reproduziert, sondern Differenz hervorbringt. Anders als bei Deleuze geht es hier jedoch nicht primär um die schöpferische Entfaltung des Neuen, sondern um Anschluss zwischen operativ getrennten Ordnungen. Übersetzung beseitigt Differenz nicht; sie macht sie anschlussfähig.","r":[{"p":"Susan Leigh Star","s":"susan-leigh-star","w":"Boundary Objects","d":"Soziologie","n":"Übersetzung ermöglicht Kooperation ohne vollständigen Konsens."},{"p":"Gilles Deleuze","s":"gilles-deleuze","w":"Différence et répétition","d":"Philosophie","n":"Wiederholung produziert Differenz statt identischer Kopie."},{"p":"Shilpa Gupta","s":"shilpa-gupta","w":"Sprach- und Grenzarbeiten","d":"Kunst","n":"Übertragung zeigt politische und mediale Bedingungen des Sprechens."},{"p":"Walter Benjamin","s":"walter-benjamin","w":"Die Aufgabe des Übersetzers","d":"Literatur","n":"Übersetzung ist Fortleben und Transformation, nicht blosse Kopie."}],"v":[9,22,30,36]},
  {"n":28,"s":"28-die-koppelung","c":"IV","t":"Die Koppelung","b":"Koppelung stabilisiert Wirkungen an Grenzen, deren Entstehung selbst zu fragen bleibt.","x":"Koppelung bezeichnet eine Beziehung, in der unterscheidbare Prozesse wiederholt füreinander wirksam werden. Ein Körper bringt Organismus, Nervensystem, Bewusstsein und Kommunikation nicht zu einer einzigen Operation zusammen. An ihm entstehen Übergänge, an denen jede Seite aus Wirkungen eigene Ereignisse bildet. Wiederholung macht solche Irritationen erwartbar, ohne Unterschiede aufzuheben. Damit erklärt der Begriff, wie getrennte Ordnungen voneinander abhängen können. Eine weitere Frage bleibt offen: Wie werden die Grenzen gezogen, an denen wir diese Ordnungen überhaupt unterscheiden? Sie lässt sich nicht allein durch erneute Berufung auf Koppelung beantworten und macht die Beziehung selbst zum Gegenstand der Beobachtung.","r":[{"p":"Niklas Luhmann","s":"niklas-luhmann","w":"Soziale Systeme","d":"Soziologie","n":"Strukturelle Koppelung verbindet operative Geschlossenheit mit Umweltabhängigkeit."},{"p":"Karen Barad","s":"karen-barad","w":"Meeting the Universe Halfway","d":"Philosophie","n":"Intraaktionen werfen die Frage auf, wie die Grenzen und Einheiten entstehen, die hier als koppelbare Ordnungen unterschieden werden."},{"p":"Pierre Huyghe","s":"pierre-huyghe","w":"After ALife Ahead","d":"Kunst","n":"Biologische, technische und räumliche Prozesse bleiben verschieden und beeinflussen einander."},{"p":"Daisy Hildyard","s":"daisy-hildyard","w":"Emergency","d":"Literatur","n":"Menschliche und mehr-als-menschliche Prozesse werden als verflochtene, nicht identische Wirklichkeiten erzählt."}],"v":[1,3,7,15,24,26,37,45]},
  {"n":29,"s":"29-das-material","c":"V","t":"Das Material","b":"Material ist der Widerstand, durch den Form möglich wird.","x":"Material ist nicht der stumme Stoff, dem eine künstlerische Idee nachträglich Form verleiht. Holz fasert, Farbe verläuft, Stoff spannt sich, Metall ermüdet, digitale Systeme erzeugen Fehler und Abhängigkeiten. Im Arbeiten antwortet Material, indem es Absichten ermöglicht, ablenkt oder zurückweist. Seine Widerstände sind keine äusseren Hindernisse, sondern Bedingungen dafür, dass etwas entstehen kann, das vorher nicht vollständig entworfen war. Auch nach seiner Bearbeitung bleibt Material tätig: Es altert, verändert seine Oberfläche und reagiert auf Licht, Feuchtigkeit, Berührung und Zeit. Kunst beginnt dort, wo diese Eigenbewegung nicht beseitigt, sondern als Mitwirkung zugelassen wird.","r":[{"p":"Annemarie Mol","s":"annemarie-mol","w":"The Body Multiple","d":"Soziologie","n":"Materialität erscheint als etwas, das in Praktiken mitwirkt und Unterschiede erzeugt."},{"p":"Jane Bennett","s":"jane-bennett","w":"Vibrant Matter","d":"Philosophie","n":"Materie wird als wirksame, nicht bloss passive Bedingung gedacht."},{"p":"Richard Serra","s":"richard-serra","w":"Verb List","d":"Kunst","n":"Materialhandlungen und Widerstände werden zu Generatoren der Form."},{"p":"Francis Ponge","s":"francis-ponge","w":"Le Parti pris des choses","d":"Literatur","n":"Dinge widersetzen sich der blossen Verfügung durch Sprache."}],"v":[25]},
  {"n":30,"s":"30-die-form","c":"V","t":"Die Form","b":"Form macht Differenz wiederverwendbar.","x":"Form ist keine Hülle, die einem Material nachträglich aufgezwungen wird. Sie ist eine vorläufige Ordnung, in der Material, Raum, Zeit, Aufmerksamkeit und Erwartung so aufeinander bezogen werden, dass eine Differenz wiederkehren kann. Eine Form bleibt nicht deshalb dieselbe, weil sie unverändert wäre. Sie bleibt wiedererkennbar, obwohl ihre Ausführung, ihr Kontext und ihre Bedeutung wechseln. Gerade diese Portabilität macht sie gesellschaftlich wirksam: Formen können zitiert, verschoben, vergessen und wiederaufgenommen werden. Wo Material Widerstand erzeugt, macht Form diesen Widerstand unterscheidbar und für weitere Operationen verfügbar. Sie speichert nichts; sie organisiert Wiederverwendbarkeit.","r":[{"p":"Caroline Levine","s":"caroline-levine","w":"Forms","d":"Soziologie","n":"Formen organisieren Relationen und können zwischen Situationen zirkulieren."},{"p":"Gilles Deleuze","s":"gilles-deleuze","w":"Différence et répétition","d":"Philosophie","n":"Form gewinnt Wiedererkennbarkeit durch Differenz in der Wiederholung."},{"p":"Constantin Brâncuși","s":"constantin-brancusi","w":"Bird in Space","d":"Kunst","n":"Variation hält eine Form über unterschiedliche materielle Ausführungen wiedererkennbar."},{"p":"Maggie Nelson","s":"maggie-nelson","w":"Bluets","d":"Literatur","n":"Eine fragmentarische Form organisiert Wiederkehr ohne lineare Einheit."}],"v":[9,27,36]},
  {"n":31,"s":"31-das-werk","c":"V","t":"Das Werk","b":"Ein Werk bleibt als bestimmte Form erkennbar; eine künstlerische Adresse kann mehrere Werke tragen.","x":"Nicht jede Form ist ein Werk. Ein Werk braucht Bedingungen, unter denen es bei veränderter Ausführung oder späterer Betrachtung als dieses Werk wiedererkannt werden kann: etwa einen Titel, eine Gestalt, eine Aufführungsregel oder eine dokumentierte Handlung. Davon unterscheidet sich die Adresse einer Künstlerin oder eines Künstlers, der mehrere Werke zugerechnet werden können. Bazon Brocks „Künstler ohne Werk“ verschiebt gerade das Verhältnis dieser beiden Adressen. Die spätere Kenntnis von Duchamps Étant donnés verändert die Erzählung über seine öffentliche Werkpause, ohne sein gesamtes Schaffen zu einem einzigen Werk zu machen. Werkidentität entsteht durch wiederholbare Zurechnung einer bestimmten Form.","r":[{"p":"Shannon Jackson","s":"shannon-jackson","w":"Social Works","d":"Soziologie","n":"Kunstwerke hängen an sozialen Infrastrukturen und Formen der Unterstützung."},{"p":"Juliane Rebentisch","s":"juliane-rebentisch","w":"Ästhetik der Installation","d":"Philosophie","n":"Werkidentität entsteht in einer offenen Relation von Objekt, Raum und Betrachter."},{"p":"Bazon Brock","s":"bazon-brock","w":"Künstler ohne Werk / Action Teaching","d":"Kunst","n":"Werkstatus kann als adressierte Praxis statt als Objekt organisiert werden."},{"p":"Enrique Vila-Matas","s":"enrique-vila-matas","w":"Bartleby y compañía","d":"Literatur","n":"Das Nicht-Schreiben wird selbst als literarisch adressierbare Form beobachtbar."}],"v":[33]},
  {"n":32,"s":"32-der-stil","c":"V","t":"Der Stil","b":"Stil ist die Wiederkehr einer Differenz als Erwartung.","x":"Stil ist nicht die Handschrift, in der sich ein unverwechselbares Inneres verrät. Das Werk bindet Form an eine Adresse; Stil entsteht, wenn an dieser Adresse über verschiedene Werke hinweg bestimmte Arten des Wählens, Verknüpfens und Weglassens wiedererkennbar werden. Ein Rhythmus, eine Leerstelle, eine Farbspannung oder selbst eine Verweigerung kann wiederkehren, ohne sich zu wiederholen. Deshalb kann Stil Medien wechseln, den Künstler überleben und sich von ihm lösen – als Schule, Epoche oder Manier. Gerade darin liegt seine Gefahr: Was zunächst Differenz erzeugte, gerinnt zur Erwartung und verlangt schliesslich vom Neuen, wieder so auszusehen wie seine frühere Abweichung.","r":[{"p":"Marielle Macé","s":"marielle-mace","w":"Façons de lire, manières d’être","d":"Soziologie","n":"Stil wird als Form des Lebens, Lesens und Wiedererkennens verstanden."},{"p":"Nelson Goodman","s":"nelson-goodman","w":"Ways of Worldmaking","d":"Philosophie","n":"Stil fungiert als symptomatische Form von Klassifikation und Referenz."},{"p":"Hanne Darboven","s":"hanne-darboven","w":"Kulturgeschichte 1880–1983","d":"Kunst","n":"Serielle Verfahren, datierte Materialien und historische Bilder verbinden Wiederholung mit einer wiedererkennbaren künstlerischen Ordnung."},{"p":"Ben Lerner","s":"ben-lerner","w":"10:04","d":"Literatur","n":"Stil entsteht in der Wiederaufnahme und Verschiebung eigener Formen."}],"v":[]},
  {"n":33,"s":"33-das-publikum","c":"V","t":"Das Publikum","b":"Das Publikum kultiviert die Empfindlichkeit getrennter Wahrnehmungen.","x":"Ein Publikum ist keine Menge, die dasselbe sieht. Wahrnehmung bleibt unübertragbar; niemand kann die Farbe, Spannung oder Langeweile eines anderen übernehmen. Gemeinsamkeit entsteht deshalb nicht im Erleben, sondern in den Anschlüssen daran. Menschen vergleichen, erzählen, widersprechen, kehren zurück und lernen dabei, auf anderes empfindlich zu werden. Das Publikum vereinigt Wahrnehmungen nicht. Es kultiviert Bedingungen, unter denen getrennte Wahrnehmungen einander irritieren und verändern können. Darin liegt seine eigentümliche Sozialität: Man muss nicht dasselbe gesehen haben, um an demselben Werk anders weiterzusehen. Öffentlichkeit beginnt dort, wo Differenz nicht beseitigt, sondern als veränderbare Empfindlichkeit wiederverwendet wird.","r":[{"p":"Antoine Hennion","s":"antoine-hennion","w":"The Passion for Music / Soziologie des amateurs","d":"Soziologie","n":"Geschmack und Empfindlichkeit entstehen in Praktiken des Sich-Einlassens."},{"p":"Juliane Rebentisch","s":"juliane-rebentisch","w":"Ästhetik der Installation","d":"Philosophie","n":"Ästhetische Erfahrung bleibt an die jeweilige Vollzugssituation gebunden."},{"p":"Lygia Clark","s":"lygia-clark","w":"Caminhando","d":"Kunst","n":"Das Schneiden eines Möbiusbandes verlagert die Arbeit in einen einmaligen Vollzug der Beteiligten."},{"p":"Italo Calvino","s":"italo-calvino","w":"Palomar","d":"Literatur","n":"Beobachtung erscheint als trainierbare und zugleich unabschliessbare Empfindlichkeit."}],"v":[3,15,23,31,47]},
  {"n":34,"s":"34-die-ausstellung","c":"V","t":"Die Ausstellung","b":"Die Ausstellung ordnet Beziehungen, bevor sie Bedeutungen ordnet.","x":"Eine Ausstellung zeigt nicht einfach Werke. Sie setzt sie in Beziehungen. Nähe, Abstand, Reihenfolge, Licht, Architektur, Beschriftung und Wegführung bestimmen mit, was gleichzeitig sichtbar wird und was sich gegenseitig verdeckt. Dasselbe Werk kann in einer anderen Nachbarschaft eine andere Frage stellen. Die Ausstellung erzeugt daher keine gemeinsame Wahrnehmung, aber sie verteilt Möglichkeiten des Sehens: Sie beschleunigt, verzögert, isoliert, verdichtet und lässt Übergänge entstehen. Ihre Ordnung bleibt vorläufig; mit jedem Schritt verändert sich das Verhältnis der Dinge erneut. Ausstellung ist deshalb weniger Behälter als Choreografie – eine räumliche Form der Koppelung, in der Werke, Körper und Erwartungen füreinander neue Empfindlichkeiten gewinnen.","r":[{"p":"Tony Bennett","s":"tony-bennett","w":"The Birth of the Museum","d":"Soziologie","n":"Ausstellungsräume organisieren Öffentlichkeit, Bewegung und Sichtbarkeit."},{"p":"Mieke Bal","s":"mieke-bal","w":"Double Exposures","d":"Philosophie","n":"Ausstellen wird als diskursive und räumliche Praxis des Zeigens gelesen."},{"p":"Fred Wilson","s":"fred-wilson","w":"Mining the Museum","d":"Kunst","n":"Neuordnung der Präsentation verändert die Lesbarkeit vorhandener Objekte."},{"p":"Olivia Laing","s":"olivia-laing","w":"Funny Weather","d":"Literatur","n":"Kunstwahrnehmung wird aus Situationen, Begegnungen und Öffentlichkeit heraus beschrieben."}],"v":[]},
  {"n":35,"s":"35-die-kunst","c":"V","t":"Die Kunst","b":"Kunst hält Wahrnehmung gesellschaftlich wiederverwendbar, indem sie ihre Differenz offenhält.","x":"Kunst ist weder Material, Form noch Werk, weder Stil, Publikum noch Ausstellung. Sie entsteht, wenn diese Unterschiede so aufeinander zurückwirken, dass Wahrnehmung gesellschaftlich wieder aufgegriffen werden kann, ohne sich in einer eindeutigen Mitteilung zu erschöpfen. Material widersteht, Form unterscheidet, das Werk bindet an eine Adresse, Stil erzeugt Erwartung, Publikum kultiviert Empfindlichkeit, Ausstellung ordnet Beziehungen. Keine dieser Operationen besitzt die Kunst für sich. Erst ihre rekursive Koppelung hält einen Bereich offen, in dem etwas wiederholt werden kann, ohne dasselbe zu bleiben. Kunst bewahrt daher keine Bedeutung. Sie organisiert die Möglichkeit, dass Wahrnehmung anders wiederkehrt.","r":[{"p":"Nathalie Heinich","s":"nathalie-heinich","w":"Le paradigme de l’art contemporain","d":"Soziologie","n":"Kunstordnungen stabilisieren sich durch Institutionen, Kategorien und Grenzverschiebungen."},{"p":"Jacques Rancière","s":"jacques-ranciere","w":"Aisthesis","d":"Philosophie","n":"Ästhetik ordnet Formen des Wahrnehmbaren und ihrer Teilhabe."},{"p":"Hito Steyerl","s":"hito-steyerl","w":"Duty Free Art","d":"Kunst","n":"Bilder zirkulieren durch heterogene institutionelle, technische und ökonomische Ordnungen."},{"p":"Michel Houellebecq","s":"michel-houellebecq","w":"La carte et le territoire","d":"Literatur","n":"Werk, Künstlerfigur, Markt und Repräsentation werden rekursiv aufeinander bezogen."}],"v":[6,37]},
  {"n":36,"s":"36-das-profil","c":"VI","t":"Das Profil","b":"Das Profil verwandelt adressierbare Spuren in berechenbare Wiedererkennbarkeit.","x":"Eine Adresse macht erreichbar; ein Profil macht wiedererkennbar. Es sammelt vergangene Klicks, Käufe, Wege, Kontakte oder Verweildauern und ordnet sie einer Adresse zu. Dabei entsteht kein Bild der ganzen Person, sondern eine Auswahl vergleichbarer Merkmale. Was als Muster erscheint, kann mit anderen Mustern verglichen und für künftige Entscheidungen verwendet werden. Dieselbe Person wird je nach Zweck in unterschiedliche berechenbare Ausschnitte zerlegt. Damit verschiebt sich Erinnerung zur Prognose: Vergangenes wird erneut verwendet, um nächste Anschlüsse wahrscheinlicher zu machen. Der adressierte Mensch und das berechnete Profil fallen nicht zusammen; dennoch kann das Profil bestimmen, was ihm als Nächstes begegnet.","r":[{"p":"Elena Esposito","s":"elena-esposito","w":"Artificial Communication, Kapitel „Getting Personal with Algorithms“","d":"Soziologie","n":"Algorithmische Profilierung adressiert Personen, ohne sie im Sinn einer persönlichen Beziehung zu kennen."},{"p":"Gilles Deleuze","s":"gilles-deleuze","w":"Post-scriptum sur les sociétés de contrôle","d":"Philosophie","n":"Datenförmige Teilungen und fortlaufende Modulation beschreiben eine Wiedererkennbarkeit, die keine vollständige Person voraussetzt."},{"p":"Sophie Calle","s":"sophie-calle","w":"The Address Book","d":"Kunst","n":"Aus den Auskünften von Menschen in einem gefundenen Adressbuch entsteht ein Porträt des Abwesenden, das keine vollständige Kenntnis seiner Person liefert."},{"p":"Jorge Luis Borges","s":"jorge-luis-borges","w":"Funes el memorioso","d":"Literatur","n":"Funes erinnert jedes Detail und kann gerade deshalb kaum abstrahieren. Erst Auswahl und Vergleich verwandeln Vergangenheit in Muster."}],"v":[4,5,8,9,10,12,15,19,27,30]},
  {"n":37,"s":"37-die-information","c":"VI","t":"Die Information","b":"Information entsteht, wenn ein Unterschied in einer bestimmten Ordnung Folgen hat.","x":"Ein Datensatz lässt sich speichern; informativ wird eine Auswahl daraus erst für eine bestimmte Frage und einen möglichen Anschluss. Derselbe Klick kann bei einer Musikempfehlung etwas anderes bewirken als bei einer Betrugsprüfung. Zwischen Aufzeichnung und Information liegen Regeln des Vergleichens, Gewichtens und Verwendens. Diese Regeln sind selbst nicht neutral: Sie entscheiden mit, welche Differenz auffällt und welche unberücksichtigt bleibt. Plattformen automatisieren Teile dieser Auswahl und verwenden ihre Ergebnisse für spätere Berechnungen. Daten sind dabei durchaus ein materieller und technischer Ausgangspunkt. Information bezeichnet hier die Wirkung eines Unterschieds innerhalb einer Beobachtungs- und Handlungsordnung.","r":[{"p":"Klaus Kusanowsky","s":"klaus-kusanowsky","w":"Überlegungen zu information expert systems","d":"Soziologie","n":"Information erscheint nicht als vorliegender Bestand, sondern als Effekt von Systemen, die Unterschiede auswählen, kombinieren und erneut zur Voraussetzung weiterer Operationen machen."},{"p":"Karen Barad","s":"karen-barad","w":"Meeting the Universe Halfway","d":"Philosophie","n":"Eigenschaften und Grenzen sind nicht einfach vorgegeben, sondern entstehen innerhalb bestimmter Anordnungen des Beobachtens und Handelns. Was als Information zählt, hängt davon ab, wie Unterschiede geschnitten werden."},{"p":"Hito Steyerl","s":"hito-steyerl","w":"In Defense of the Poor Image","d":"Kunst","n":"Die Zirkulation und Bearbeitung digitaler Bilder verändern deren Wert, Lesbarkeit und mögliche Verwendung."},{"p":"Stanisław Lem","s":"stanislaw-lem","w":"His Master’s Voice","d":"Literatur","n":"Ein vermeintliches ausserirdisches Signal konfrontiert Wissenschaftler mit der Frage, ob eine empfangene Differenz überhaupt Information ist. Bedeutung entsteht nicht aus dem Signal allein."}],"v":[1,6,28,35]},
  {"n":38,"s":"38-die-wahrscheinlichkeit","c":"VI","t":"Die Wahrscheinlichkeit","b":"Wahrscheinlichkeit verwandelt offene Kontingenz in ungleich gewichtete Zukunft.","x":"Wahrscheinlichkeit beseitigt Kontingenz nicht. Sie ordnet sie. Zwischen dem, was geschehen ist, und dem, was geschehen könnte, entsteht eine Verteilung ungleicher Erwartungen. Das Unwahrscheinliche bleibt möglich, wird aber anders behandelt als das Wahrscheinliche. Dadurch lässt sich Zukunft operativ bearbeiten, ohne sie kennen zu müssen. Für Plattformen ist diese Verschiebung entscheidend: Ein Profil muss nicht sagen, was jemand tun wird. Es genügt, verschiedene nächste Anschlüsse unterschiedlich wahrscheinlich zu machen. Wahrscheinlichkeit verwandelt Unwissen in eine vergleichbare Form. Sie reduziert Zukunft, ohne sie festzulegen – und bereitet gerade dadurch die Selektion vor.","r":[{"p":"Barbara Adam","s":"barbara-adam","w":"Arbeiten zur gesellschaftlichen Zukunft","d":"Soziologie","n":"Zukünftiges wird bereits gegenwärtig durch Erwartungen, Planungen und Risiken wirksam, obwohl es nicht gegenwärtig gemacht werden kann."},{"p":"Ian Hacking","s":"ian-hacking","w":"The Emergence of Probability","d":"Philosophie","n":"Wahrscheinlichkeit misst nicht bloss Unsicherheit; sie etabliert eine eigene Weise, mit Ereignissen umzugehen, deren einzelne Ausgänge unbestimmt bleiben."},{"p":"Vera Molnár","s":"vera-molnar","w":"(Des)Ordres","d":"Kunst","n":"Systematische Anordnungen konzentrischer Quadrate werden durch programmierte Abweichungen gestört; Zufall wirkt innerhalb einer gestalteten Regel."},{"p":"Thomas Pynchon","s":"thomas-pynchon","w":"Gravity’s Rainbow","d":"Literatur","n":"Statistik, Vorhersage und Wahrscheinlichkeit verschieben die Grenze zwischen Beobachtung und Steuerung."}],"v":[2,6]},
  {"n":39,"s":"39-der-algorithmus","c":"VI","t":"Der Algorithmus","b":"Algorithmisches Ranking verteilt ungleiche Chancen auf den nächsten Anschluss.","x":"Auf Plattformen ordnen algorithmische Auswahlverfahren Inhalte und Vorschläge: relevanter oder weniger relevant, sichtbar oder unsichtbar, zuerst oder später. Solche Verfahren können aus Daten Wahrscheinlichkeiten berechnen und sie in ein konkretes Ranking übersetzen. Dafür braucht es zuvor Entscheidungen darüber, was gesammelt, beschriftet und als Erfolg gewertet wird. Die Macht dieses Rankings liegt darin, die Gegenwart ungleich vorzubereiten. Was höher steht, erhält eher Gelegenheit, einen weiteren Anschluss auszulösen; was selten gezeigt wird, bleibt leichter unbeachtet. Nutzende können widersprechen oder anders wählen. Doch auch ihre Abweichungen treffen auf eine bereits geordnete Auswahl und können wieder als Daten eingehen.","r":[{"p":"Tarleton Gillespie","s":"tarleton-gillespie","w":"The Relevance of Algorithms","d":"Soziologie","n":"Algorithmen stellen gesellschaftlich relevante Ordnungen des Sichtbaren her. Relevanz ist kein neutrales Finden bereits vorhandener Wichtigkeit."},{"p":"Yuk Hui","s":"yuk-hui","w":"On the Existence of Digital Objects","d":"Philosophie","n":"Digitale Operationen bringen Relationen hervor und organisieren sie; ein digitales Objekt besteht nicht unabhängig von den Verfahren seiner Aktualisierung."},{"p":"Anna Ridler","s":"anna-ridler","w":"Myriad (Tulips)","d":"Kunst","n":"Tausende von Hand beschriftete Tulpenfotografien machen die Auswahl- und Klassifikationsarbeit sichtbar, auf der maschinelles Lernen beruht."},{"p":"Patricia Lockwood","s":"patricia-lockwood","w":"No One Is Talking About This","d":"Literatur","n":"Der Portal-Strom des Romans zeigt eine Gegenwart, deren Wahrnehmung bereits durch Reihenfolge, Wiederholung und technische Selektion organisiert ist."}],"v":[]},
  {"n":40,"s":"40-die-empfehlung","c":"VI","t":"Die Empfehlung","b":"Die Empfehlung gibt berechnete Wahrscheinlichkeit als mögliche nächste Welt zurück.","x":"Die Empfehlung ist der Moment, in dem Berechnung die Grenze des Modells überschreitet. Eine Wahrscheinlichkeit, die intern nur Zahl, Gewicht oder Rang war, erscheint nun als Gegenstand der Welt: dieses Lied, dieser Mensch, dieses Video, dieser Weg. Empfehlung zwingt nicht. Gerade deshalb ist sie wirksam. Sie besetzt eine mögliche nächste Stelle, bevor eine eigene Suche begonnen hat, und präsentiert diese Vorbesetzung als Hilfe. Die Prognose wird dadurch sozial anschlussfähig. Was berechnet wurde, kann gewählt, ignoriert, geteilt oder zurückgewiesen werden. Jede dieser Reaktionen erzeugt zugleich neue Spuren. Empfehlung ist deshalb Selektion und Messinstrument in derselben Operation.","r":[{"p":"Taina Bucher","s":"taina-bucher","w":"If...Then","d":"Soziologie","n":"Algorithmische Macht zeigt sich nicht nur in verborgener Berechnung, sondern auch in den Situationen und Empfindungen, die Algorithmen für Nutzende erzeugen."},{"p":"Bernard Stiegler","s":"bernard-stiegler","w":"Taking Care of Youth and the Generations","d":"Philosophie","n":"Technische Aufmerksamkeitsordnungen greifen in kulturelle Erinnerung und die Bildung künftiger Erwartungen ein."},{"p":"Amalia Ulman","s":"amalia-ulman","w":"Excellences & Perfections","d":"Kunst","n":"Die Arbeit benutzt die Erwartungen sozialer Plattformen als Material und zeigt, wie Selbstdarstellung innerhalb bereits etablierter Muster von Sichtbarkeit operiert."},{"p":"Dave Eggers","s":"dave-eggers","w":"The Circle","d":"Literatur","n":"Personalisierung erscheint als Dienstleistung und zugleich als fortschreitende Organisation dessen, was sichtbar, erwartbar und sozial anschlussfähig wird."}],"v":[]},
  {"n":41,"s":"41-der-feed","c":"VI","t":"Der Feed","b":"Der Feed macht Prognose zur gegenwärtigen Umwelt ihrer nächsten Überprüfung.","x":"Der Feed ordnet Empfehlungen zu einer Gegenwart. Er zeigt nicht einfach, was vorhanden ist, sondern erzeugt eine fortlaufende Umwelt aus bereits gewichteten Möglichkeiten. Jede Auswahl erscheint dabei als Jetzt: sichtbar, anklickbar, kommentierbar, überspringbar. Doch dieses Jetzt ist aus Vergangenheit berechnet und auf weitere Datenerzeugung angelegt. Der Feed prognostiziert nicht nur Verhalten; er stellt die Situation her, in der das prognostizierte Verhalten stattfinden kann. Damit wird Vorhersage rekursiv. Was gezeigt wird, beeinflusst, was getan wird; was getan wird, verändert, was künftig gezeigt werden kann. Der Feed ist die Gegenwart einer Prognose, die ihre eigenen Voraussetzungen nachliefert.","r":[{"p":"José van Dijck","s":"jose-van-dijck","w":"The Culture of Connectivity","d":"Soziologie","n":"Plattformen organisieren Verbindungen als technische und kulturelle Ordnung programmierter Konnektivität."},{"p":"Byung-Chul Han","s":"byung-chul-han","w":"Arbeiten zur digitalen Gegenwart","d":"Philosophie","n":"Digitale Kommunikation erzeugt eine hoch beschleunigte Aktualisierungsordnung, in der Dauer schwerer auszubilden ist."},{"p":"Christian Marclay","s":"christian-marclay","w":"The Clock","d":"Kunst","n":"Tausende Filmfragmente werden zu einer Gegenwart montiert, die fortlaufend auf ihre eigene Zeit verweist. Der Strom besteht aus diskreten Selektionen."},{"p":"Jenny Offill","s":"jenny-offill","w":"Weather","d":"Literatur","n":"Kurze Beobachtungen, Nachrichten und Krisenmeldungen bilden eine unterbrochene, nur im Lesen verknüpfte Gegenwart."}],"v":[7]},
  {"n":42,"s":"42-die-plattform","c":"VI","t":"Die Plattform","b":"Die Plattform gibt berechnete Möglichkeiten als Umwelt zurück und verarbeitet deren Folgen.","x":"Die Plattform verbindet Profile, Daten, Berechnungen, Empfehlungen und Feeds zu einer Rückkopplung. Sie beobachtet Verhalten, verdichtet es zu Mustern und stellt ausgewählte Möglichkeiten als neue Umwelt bereit. Diese Umwelt beeinflusst weitere Handlungen, die erneut beobachtet werden können. Der Kreis bleibt offen: Menschen, Institutionen, Ereignisse und technische Fehler bringen Abweichungen hervor. Wo Systeme zusätzlich Texte, Bilder oder Antworten erzeugen, werden auch diese Ausgaben zu möglichen nächsten Anlässen der Kommunikation. Die Plattform organisiert so nicht nur Sichtbarkeit, sondern verändert, woran angeschlossen werden kann. Ihre Prognosen gewinnen Wirkung, indem sie an der Gegenwart mitarbeiten, an der sie später überprüft werden.","r":[{"p":"David Beer","s":"david-beer","w":"Metric Power; The Data Gaze","d":"Soziologie","n":"Messung und Datenanalyse beschreiben Gesellschaft nicht bloss, sondern bringen Klassifikationen, Bewertungen und Handlungsmöglichkeiten mit hervor."},{"p":"Luciana Parisi","s":"luciana-parisi","w":"Contagious Architecture","d":"Philosophie","n":"Algorithmische Berechnung ist nicht reine Ausführung eines vollständig vorgegebenen Plans; sie produziert Relationen und Resultate, deren konkrete Form nicht einfach ausgeschrieben ist."},{"p":"Rafael Lozano-Hemmer","s":"rafael-lozano-hemmer","w":"Pulse Room","d":"Kunst","n":"Körperliche Signale des Publikums werden in eine technische Umwelt übersetzt, die sich mit jeder neuen Teilnahme verändert. Beobachtung wird Bestandteil der nächsten Situation."},{"p":"Jennifer Egan","s":"jennifer-egan","w":"The Candy House","d":"Literatur","n":"Externalisiertes Gedächtnis, soziale Netzwerke und algorithmische Auswertung verbinden Vergangenheit mit neuer technischer Handlungswirksamkeit."}],"v":[]},
  {"n":43,"s":"43-die-identitaet","c":"VII","t":"Die Identität","b":"Identität macht Veränderung intertemporal zurechenbar.","x":"Identität ist nicht die Gleichheit eines Dinges mit sich selbst. Sie entsteht dort, wo Veränderung über Zeit hinweg derselben Adresse zugerechnet werden kann. Eine Person, ein Werk oder eine Organisation bleibt nicht identisch, weil alles gleich bleibt, sondern weil Unterschiede als Veränderungen von etwas Wiedererkennbarem behandelt werden. Identität vermittelt deshalb zwischen Erfahrung und Erwartung. Sie hält genug Kontinuität fest, damit Abweichung überhaupt auffallen kann, und genug Offenheit, damit Veränderung zurechenbar bleibt. Gegen Plattformprofile wird diese Unterscheidung wichtig: Berechenbare Wiedererkennbarkeit ist noch keine Identität. Identität ist die Form, in der Veränderung fortgesetzt werden kann, ohne in Gleichheit aufzugehen.","r":[{"p":"Anselm Strauss","s":"anselm-strauss","w":"Mirrors and Masks","d":"Soziologie","n":"Identität erscheint nicht als unveränderlicher Kern, sondern als etwas, das sich in sozialen Beziehungen und biografischen Übergängen fortlaufend bildet."},{"p":"Paul Ricœur","s":"paul-ricoeur","w":"Oneself as Another","d":"Philosophie","n":"Die Unterscheidung von idem und ipse trennt Gleichheit von Selbigkeit: Jemand kann derselbe bleiben, ohne in allen Eigenschaften gleich zu bleiben."},{"p":"Gillian Wearing","s":"gillian-wearing","w":"Album","d":"Kunst","n":"Maskierte Rekonstruktionen von Familienfotografien lösen sichtbare Ähnlichkeit und personale Fortdauer voneinander; hier tritt die Frage der eigenen Identität hervor."},{"p":"Virginia Woolf","s":"virginia-woolf","w":"Orlando","d":"Literatur","n":"Orlando bleibt als Figur zurechenbar, obwohl Jahrhunderte, soziale Rollen und Geschlecht wechseln. Identität wird durch Veränderung erzählbar."}],"v":[2,7,18]},
  {"n":44,"s":"44-die-moeglichkeit","c":"VII","t":"Die Möglichkeit","b":"Möglichkeit ist die gegenwärtige Erreichbarkeit eines noch nicht aktualisierten Anschlusses.","x":"Möglichkeit ist kein Vorrat unsichtbarer Welten hinter der Wirklichkeit. Sie wird gegenwärtig mitgeführt, wenn ein Anschluss als realisierbar, denkbar oder erwartbar erscheint, ohne bereits aktualisiert zu sein. Jede Struktur begrenzt solche Möglichkeiten, sonst wäre keine Auswahl möglich. Aber sie vernichtet sie nicht notwendig. Eine Tür eröffnet andere Anschlüsse als eine Wand; eine Sprache andere Sätze als Schweigen; eine Institution andere Entscheidungen als eine private Laune. Möglichkeit ist deshalb strukturierte Offenheit. Sie besteht nicht im Beliebigen, sondern darin, dass eine gegenwärtige Ordnung mehr als eine eigene Fortsetzung zulässt. Zukunft beginnt dort, wo dieses Mehr praktisch erreichbar bleibt.","r":[{"p":"Ann Mische","s":"ann-mische","w":"Projects and Possibilities: Researching Futures in Action","d":"Soziologie","n":"Zukünfte werden in gegenwärtigem Handeln entworfen, verglichen und sozial verhandelt."},{"p":"Ernst Bloch","s":"ernst-bloch","w":"Das Prinzip Hoffnung","d":"Philosophie","n":"Das Noch-Nicht ist kein blosses Nichts, sondern gegenwärtige Offenheit auf Möglichkeiten hin, deren Realisierung von konkreten Bedingungen abhängt."},{"p":"Yoko Ono","s":"yoko-ono","w":"Grapefruit","d":"Kunst","n":"Instruktionen schlagen mögliche Handlungen vor. Ihre Form legt Bedingungen fest, ohne die jeweilige Aktualisierung vollständig zu bestimmen."},{"p":"Robert Musil","s":"robert-musil","w":"Der Mann ohne Eigenschaften","d":"Literatur","n":"Der Möglichkeitssinn bezeichnet die Fähigkeit, Wirklichkeit nicht mit ihrer Notwendigkeit zu verwechseln und andere Ordnungen mitzusehen."}],"v":[19]},
  {"n":45,"s":"45-die-kontingenz","c":"VII","t":"Die Kontingenz","b":"Kontingenz wird zur Zukunftschance, wo Alternativen erreichbar und Strukturen revidierbar bleiben.","x":"Kontingent ist, was so ist und auch anders sein könnte. Diese Andersmöglichkeit ist nicht schon eine praktisch verfügbare Alternative. Eine Ordnung kann veränderbar sein, während Menschen gerade keinen Zugang zu den Mitteln ihrer Veränderung haben. Erwartungen, Regeln und Wahrscheinlichkeiten begrenzen die nächsten Anschlüsse; dadurch ermöglichen sie Entscheidungen. Entscheidend ist, ob solche Begrenzungen bearbeitbar bleiben. Eine unbestimmte Situation bietet ebenso wenig Halt wie eine, die jede Abweichung ausschliesst. Für Zukunft braucht es Strukturen, die Auswahl erlauben und Revision ermöglichen. Die Frage nach Kontingenz führt deshalb weiter zur Frage, wer Alternativen tatsächlich erkennen, erproben und erreichen kann.","r":[{"p":"Niklas Luhmann","s":"niklas-luhmann","w":"Arbeiten zum Kontingenzbegriff","d":"Soziologie","n":"Kontingent ist, was weder notwendig noch unmöglich ist. Strukturen reduzieren Komplexität und führen zugleich einen Horizont anderer Möglichkeiten mit."},{"p":"Judith Butler","s":"judith-butler","w":"Arbeiten zur Wiederholung von Normen","d":"Philosophie","n":"Normen stabilisieren sich durch Wiederholung, ohne dadurch notwendig zu werden. Gerade die Wiederholung lässt Variation und Verschiebung zu."},{"p":"Mona Hatoum","s":"mona-hatoum","w":"Arbeiten mit verschobenen Alltagsgegenständen und Räumen","d":"Kunst","n":"Vertraute Formen bleiben erkennbar und erscheinen zugleich als anders möglich; Selbstverständlichkeit wird instabil."},{"p":"Milan Kundera","s":"milan-kundera","w":"Die unerträgliche Leichtigkeit des Seins","d":"Literatur","n":"Weil ein Leben nicht probeweise wiederholt werden kann, bleiben Notwendigkeit und Zufall unentscheidbar verschränkt."}],"v":[1,3,7,15,17,18,22,24,26,28]},
  {"n":46,"s":"46-die-unterbrechung","c":"VII","t":"Die Unterbrechung","b":"Eine Unterbrechung öffnet Zukunft erst, wenn nach ihr etwas anders anschliessen kann.","x":"Eine Unterbrechung erzeugt noch keine Zukunft. Ein Ausfall, ein Schock oder eine Verweigerung kann eine Folge ebenso gut zerstören, lähmen oder zu ihrer alten Form zurückzwingen. Entscheidend ist, ob durch die Unterbrechung eine andere Fortsetzung anschlussfähig wird. Erst dann verändert sie die Struktur des Weitergehens. Das gilt für Gespräche, Institutionen, Kunstwerke und technische Systeme. Unterbrechung ist deshalb keine romantische Gegenfigur zur Ordnung. Sie ist eine Prüfung der Ordnung: Kann sie Abweichung aufnehmen, ohne sie sofort zu normalisieren oder abzubrechen? Zukunft entsteht nicht im Riss selbst, sondern in den Anschlüssen, die der Riss möglich macht.","r":[{"p":"Harold Garfinkel","s":"harold-garfinkel","w":"Studies in Ethnomethodology / Breaching Experiments","d":"Soziologie","n":"Störungen alltäglicher Erwartungen provozieren häufig Reparaturleistungen. Eine Normverletzung erzeugt nicht automatisch eine neue Ordnung."},{"p":"Hannah Arendt","s":"hannah-arendt","w":"The Human Condition","d":"Philosophie","n":"Mit Natalität verbindet Arendt Handeln mit der Möglichkeit eines Anfangs. Entscheidend ist nicht der Bruch allein, sondern dass eine neue Folge beginnen kann."},{"p":"Doris Salcedo","s":"doris-salcedo","w":"Shibboleth","d":"Kunst","n":"Ein Riss im Boden der Tate Modern macht Trennung räumlich gegenwärtig und zwingt die Institution, Architektur und Geschichte anders wahrzunehmen."},{"p":"Samuel Beckett","s":"samuel-beckett","w":"Waiting for Godot","d":"Literatur","n":"Auf unzählige Unterbrechungen folgt gerade kein wirklicher Neubeginn. Der negative Fall zeigt, dass Aufschub die Struktur der Fortsetzung nicht notwendig verändert."}],"v":[9,10,12,14,19,24]},
  {"n":47,"s":"47-das-neue","c":"VII","t":"Das Neue","b":"Neu ist, was verändert, was anschliessend möglich ist.","x":"Das Neue ist nicht einfach das, was vorher nicht da war. Überraschungen können folgenlos bleiben, Moden verschwinden, Zufälle sich sofort in bekannte Muster einfügen. Neuheit wird theoretisch erst dort interessant, wo ein Ereignis verändert, was danach möglich ist. Es verschiebt Erwartungen, Regeln, Wahrnehmungen oder Beziehungen und erzeugt Anschlussformen, die vorher nicht auf dieselbe Weise erreichbar waren. Deshalb kann auch Wiederholung neu sein: wenn sie ihre Bedingungen verändert. Das Neue steht nicht ausserhalb der Geschichte, sondern greift in ihre Fortsetzung ein. Es ist keine Eigenschaft eines Gegenstands, sondern eine Differenz im Raum der folgenden Möglichkeiten.","r":[{"p":"Michel Callon","s":"michel-callon","w":"The Sociology of an Actor-Network: The Case of the Electric Vehicle","d":"Soziologie","n":"Eine technische Neuerung wird erst in einem Geflecht von Beteiligten, Interessen und Gegenständen wirksam."},{"p":"Gilbert Simondon","s":"gilbert-simondon","w":"L’individuation à la lumière des notions de forme et d’information","d":"Philosophie","n":"Individuation geht aus metastabilen Situationen hervor. Neues entsteht, indem vorhandene Spannungen eine Form hervorbringen, die weitere Individuation verändert."},{"p":"Lygia Clark","s":"lygia-clark","w":"Caminhando","d":"Kunst","n":"Der einmalige Schnitt verändert, was danach an der fortlaufenden Form noch möglich ist; hier steht die Wirkung auf den nächsten Handlungsschritt im Vordergrund."},{"p":"Ursula K. Le Guin","s":"ursula-k-le-guin","w":"The Dispossessed","d":"Literatur","n":"Zwei unterschiedlich organisierte Gesellschaften zeigen, wie Regeln Möglichkeiten eröffnen und begrenzen und im Konflikt verändert werden können."}],"v":[3,8,23,33]},
  {"n":48,"s":"48-die-freiheit","c":"VII","t":"Die Freiheit","b":"Freiheit ist die Fähigkeit, strukturierte Kontingenz aufzunehmen, zurückzuweisen oder umzuformen.","x":"Freiheit ist weder Beliebigkeit noch Abwesenheit von Bedingungen. Handeln ist immer strukturiert: durch Körper, Sprache, Geschichte, Institutionen, Technik und andere Menschen. Freiheit zeigt sich deshalb nicht darin, ohne Voraussetzungen zu beginnen, sondern darin, mit ihnen anders umgehen zu können. Eine Erwartung kann übernommen, zurückgewiesen, verschoben oder umgeformt werden; eine Regel kann befolgt, ausgelegt oder zum Gegenstand neuer Regeln gemacht werden. Freiheit benötigt Möglichkeiten, aber auch Fähigkeiten und Bedingungen, sie wahrzunehmen und zu bearbeiten. Sie ist strukturierte Verfügung über Kontingenz. Unfreiheit beginnt dort, wo Alternativen formal bestehen, aber praktisch nicht mehr anschlussfähig werden.","r":[{"p":"Pierre Bourdieu","s":"pierre-bourdieu","w":"Arbeiten zu Habitus und Praxis","d":"Soziologie","n":"Praktiken sind weder frei von Geschichte noch mechanisch determiniert; sie entstehen als strukturierte Improvisationen innerhalb ungleich verteilter Möglichkeitsräume."},{"p":"Simone de Beauvoir","s":"simone-de-beauvoir","w":"Pour une morale de l’ambiguïté","d":"Philosophie","n":"Freiheit ist situiert. Sie verwirklicht sich nicht ausserhalb von Bedingungen und anderen Freiheiten, sondern in der Auseinandersetzung mit ihnen."},{"p":"Tania Bruguera","s":"tania-bruguera","w":"Arte Útil","d":"Kunst","n":"Kunst wird als gesellschaftliche Handlungsmöglichkeit untersucht. Entscheidend ist, ob Situationen entstehen, in denen Beteiligte tatsächlich anders handeln können."},{"p":"Ralph Ellison","s":"ralph-ellison","w":"Invisible Man","d":"Literatur","n":"Handlungsspielraum entsteht zunehmend dort, wo der Erzähler sich weigert, vollständig in den von anderen angebotenen Identitäten aufzugehen."}],"v":[16]},
  {"n":49,"s":"49-die-zukunft","c":"VII","t":"Die Zukunft","b":"Zukunft ist der erhaltene Spielraum, anders weiterzugehen, als bereits erwartet wird.","x":"Spätere Ereignisse werden eintreten, gleichgültig, wie offen eine Ordnung heute ist. Zukunft meint in diesem Projekt mehr: den gegenwärtigen Spielraum für Fortsetzungen, die noch nicht vollständig erwartet oder vorbereitet sind. Jede Ordnung muss Möglichkeiten einschränken, um handeln zu können. Sie gefährdet ihre eigene Zukunftsfähigkeit, wenn sie Abweichungen nur noch als Fehler behandeln und Alternativen nicht mehr erreichen kann. Offenheit besteht weder im Beliebigen noch in der Zusicherung eines besseren Ausgangs. Sie zeigt sich daran, ob Erfahrungen, Einsprüche und neue Bedingungen eine Fortsetzung verändern können. Die Zukunft der Strophe ist dieser erhaltene Überschuss des Andersweitergehens über die bereits organisierte Erwartung.","r":[{"p":"Helga Nowotny","s":"helga-nowotny","w":"Time: The Modern and Postmodern Experience","d":"Soziologie","n":"Eine erweiterte Gegenwart zieht immer grössere Teile der Zukunft durch Planung und Erwartung in gegenwärtige Entscheidungen hinein."},{"p":"Alfred North Whitehead","s":"alfred-north-whitehead","w":"Process and Reality","d":"Philosophie","n":"Wirklichkeit besteht aus Ereignissen des Werdens; Kreativität bezeichnet die Möglichkeit, dass aus Gegebenem eine neue konkrete Ordnung entsteht."},{"p":"Katie Paterson","s":"katie-paterson","w":"Future Library","d":"Kunst","n":"Das Werk organisiert Zukunft über hundert Jahre sehr genau und hält zugleich offen, welche Texte, Leserinnen und gesellschaftlichen Bedingungen einmal zusammentreffen."},{"p":"Ted Chiang","s":"ted-chiang","w":"Story of Your Life; What’s Expected of Us","d":"Literatur","n":"Die Erzählungen prüfen, wie sich Handeln verändert, wenn Zukunft vorhersehbar erscheint, und unterscheiden Wissen über Kommendes von Handlungsmöglichkeit."}],"v":[2]}
];
export const UEBUNGEN = [
  {"id":"001","n":"Farbinventar","t":"Farbe","nb":[],"v":0,"s":0,"d":8,"a":"Suche in deiner unmittelbaren Umgebung zehn unterschiedliche Farben und lege oder fotografiere sie als kleine Sammlung.","m":"Umgebung, optional Kamera/Farbpapier","f":"Hat die Suche deinen Blick auf Farben verändert? Wie?"},
  {"id":"002","n":"Fast gleich","t":"Farbe","nb":[],"v":0,"s":1,"d":10,"a":"Finde fünf Farbtöne, die auf den ersten Blick fast gleich wirken, und ordne sie von wärmer zu kühler oder heller zu dunkler.","m":"Umgebung/Farbmaterial","f":"Ab welchem Paar konntest du den Unterschied sicher benennen – oder bei keinem?"},
  {"id":"003","n":"Komplementärfund","t":"Farbe","nb":[],"v":0,"s":0,"d":8,"a":"Suche drei Paare von Farben, die sich stark gegenseitig steigern. Lege jedes Paar nebeneinander.","m":"Umgebung/Farbpapier","f":"Welches Paar wirkt am stärksten, und was trägt dazu bei?"},
  {"id":"004","n":"Warm–kühl-Feld","t":"Farbe","nb":[],"v":0,"s":1,"d":10,"a":"Sammle je fünf warme und fünf kühle Farbfunde. Suche danach einen Farbton, der je nach Nachbarschaft kippt.","m":"Farbmaterial/Umgebung","f":"Gab es Farbtöne, die sich nicht eindeutig zuordnen ließen? Welche?"},
  {"id":"005","n":"Licht verändert Farbe","t":"Farbe","nb":[],"v":0,"s":0,"d":10,"a":"Beobachte denselben farbigen Gegenstand an drei Orten oder Lichtbedingungen und notiere/fotografiere die Veränderungen.","m":"ein farbiger Gegenstand","f":"Was blieb gleich, obwohl die Farbe anders erschien?"},
  {"id":"006","n":"Druckfarben-Archiv","t":"Farbe","nb":["Raum & Material"],"v":0,"s":0,"d":12,"a":"Schneide oder markiere zehn interessante Farben aus Verpackungen, Magazinen oder Drucksachen und sortiere sie ohne Farbnamen.","m":"Drucksachen, Schere","f":"Nach welchem visuellen Kriterium hast du tatsächlich sortiert?"},
  {"id":"007","n":"Linienbibliothek","t":"Linie","nb":[],"v":0,"s":0,"d":10,"a":"Finde zehn verschiedene Linien in Dingen um dich herum: gerade, geknickt, weich, unterbrochen, gespannt … Zeichne nur die Linien ab.","m":"Papier, Stift","f":"Welche Linie beschreibt ihren Gegenstand am wenigsten eindeutig?"},
  {"id":"008","n":"Bewegungslinien","t":"Linie","nb":["Zeit & Körper"],"v":0,"s":1,"d":8,"a":"Beobachte drei Bewegungen im Alltag und übersetze jede in nur zwei oder drei Linien.","m":"Papier, Stift","f":"Welche Linie vermittelt Bewegung, obwohl nichts dargestellt ist?"},
  {"id":"009","n":"Geometrisch / organisch","t":"Form","nb":[],"v":0,"s":0,"d":8,"a":"Suche zehn Formen und teile sie in geometrisch, organisch oder unentscheidbar ein.","m":"Umgebung, Papier/Kamera","f":"Gab es Formen, die sich der Einteilung entzogen? Welche?"},
  {"id":"010","n":"Formen ohne Dinge","t":"Form","nb":["Linie"],"v":0,"s":0,"d":10,"a":"Suche fünf interessante Formen, ohne den Gegenstand zu benennen. Zeichne nur ihre Silhouette.","m":"Papier, Stift","f":"Ab wann hast du das Gebilde nur noch als Form gelesen – oder gelang das nicht?"},
  {"id":"011","n":"Texturquartett","t":"Raum & Material","nb":[],"v":0,"s":0,"d":12,"a":"Finde vier deutlich verschiedene Oberflächen und dokumentiere sie als Zeichnung, Frottage oder Foto.","m":"Papier, weicher Stift, Umgebung","f":"Welche Textur ließ sich visuell leichter, welche schwerer übertragen?"},
  {"id":"012","n":"Tastarchiv","t":"Raum & Material","nb":[],"v":0,"s":0,"d":8,"a":"Wähle fünf ungefährliche Materialien und ordne sie nur nach Tastqualität: glatt, rau, weich, hart, elastisch usw.","m":"fünf Materialien","f":"Welche Materialien fühlten sich ähnlich an, welche verschieden – und deckt sich das mit dem Aussehen?"},
  {"id":"013","n":"Ein Material – fünf Zustände","t":"Raum & Material","nb":[],"v":0,"s":0,"d":10,"a":"Sammle oder erzeuge fünf Zustände desselben Materials, z. B. Papier glatt, geknickt, gerissen, gerollt, zerknüllt.","m":"ein Material","f":"Welche Veränderung hat das Material am stärksten verwandelt?"},
  {"id":"014","n":"Kantenfinder","t":"Linie","nb":[],"v":0,"s":0,"d":8,"a":"Suche in deiner Umgebung fünf verschiedene Kanten: eine weiche, eine scharfe, eine gezackte, eine gebrochene und eine, an der sich zwei Dinge überlagern. Zeichne von jeder Kante frei von Hand, während du sie ansiehst, nur die Linie, an der zwei Flächen aufeinandertreffen – nicht die Gegenstände selbst.","m":"Papier, Stift","f":"Welche Kante gehört eigentlich zu zwei Dingen gleichzeitig?"},
  {"id":"015","n":"Negativräume","t":"Form","nb":["Raum & Material"],"v":0,"s":1,"d":10,"a":"Suche fünf Zwischenräume zwischen Dingen und zeichne nur diese Leerformen.","m":"Papier, Stift","f":"Wann wirkt der Zwischenraum selbst wie ein Gegenstand?"},
  {"id":"016","n":"Wiederholungen finden","t":"Form","nb":[],"v":0,"s":0,"d":10,"a":"Suche eine wiederkehrende Form oder Struktur und sammle sechs Varianten davon.","m":"Umgebung, Kamera/Skizzenbuch","f":"Was muss gleich bleiben, damit du noch von Wiederholung sprichst?"},
  {"id":"017","n":"Symmetrie / Störung","t":"Form","nb":["Raum & Material"],"v":0,"s":0,"d":8,"a":"Finde drei annähernd symmetrische Situationen und jeweils die Stelle, an der die Symmetrie bricht.","m":"Umgebung, Kamera/Skizzenbuch","f":"Welche kleine Abweichung verändert das Ganze am meisten?"},
  {"id":"018","n":"Zufallsspuren","t":"Form","nb":["Linie","Zufall"],"v":0,"s":0,"d":10,"a":"Suche fünf unbeabsichtigte Spuren: Flecken, Risse, Abrieb, Tropfen, Klebereste. Zeichne sie als reine Formen ab.","m":"Umgebung, Papier, Stift","f":"Wann wird eine Spur zur Komposition?"},
  {"id":"019","n":"Schattenformen","t":"Form","nb":["Linie"],"v":0,"s":0,"d":10,"a":"Sammle fünf Schatten als Umriss und vergleiche sie mit den Dingen, die sie erzeugen.","m":"Papier/Kamera, Licht","f":"Welcher Schatten wirkt eigenständiger als sein Gegenstand?"},
  {"id":"020","n":"Durchsicht und Spiegelung","t":"Raum & Material","nb":[],"v":0,"s":1,"d":10,"a":"Suche fünf Stellen, an denen du durch etwas hindurch oder in etwas hinein siehst: Glas, Wasser, Spiegel, Folie.","m":"Umgebung, Kamera/Skizzenbuch","f":"Wo sind Vordergrund und Hintergrund am schwersten zu trennen?"},
  {"id":"021","n":"Verbindungen","t":"Raum & Material","nb":[],"v":0,"s":1,"d":12,"a":"Finde fünf verschiedene Arten, wie Dinge verbunden sind: Knoten, Steckung, Scharnier, Klebung, Druck, Überlappung.","m":"Umgebung, Skizzenbuch","f":"Welche Verbindung nutzt das Material am unmittelbarsten?"},
  {"id":"022","n":"Drei Ausschnitte","t":"Form","nb":["Raum & Material"],"v":0,"s":0,"d":8,"a":"Baue mit den Fingern oder einem Papierrahmen einen Sucher und sammle drei Ausschnitte derselben Szene.","m":"Papierrahmen optional","f":"Wie verändert der Rahmen, was wichtig erscheint?"},
  {"id":"023","n":"Fünf Distanzen","t":"Form","nb":["Raum & Material"],"v":0,"s":0,"d":10,"a":"Betrachte dasselbe Objekt aus fünf Distanzen und notiere jeweils nur drei sichtbare Merkmale.","m":"Objekt, Papier","f":"Ab welcher Distanz verschwindet das Detail und entsteht die Gesamtform?"},
  {"id":"024","n":"Fünf Blickwinkel","t":"Form","nb":["Linie"],"v":0,"s":0,"d":8,"a":"Betrachte denselben Gegenstand von oben, unten, vorne, hinten und schräg und zeichne je eine 30-Sekunden-Silhouette.","m":"Objekt, Papier, Stift","f":"Welche Ansicht war am leichtesten, welche am schwersten wiederzuerkennen?"},
  {"id":"025","n":"Fünf Helligkeiten","t":"Farbe","nb":[],"v":0,"s":0,"d":8,"a":"Suche fünf Flächen von sehr hell bis sehr dunkel und ordne sie als Werteskala.","m":"Umgebung, Kamera/Papier","f":"Liegen die fünf Werte gleichmäßig auseinander, oder liegen manche näher beieinander?"},
  {"id":"026","n":"Geräuschlinien","t":"Linie","nb":["Zeit & Körper"],"v":0,"s":0,"d":5,"a":"Höre zwei Minuten lang und sammle fünf Geräusche als unterschiedliche Linien, ohne die Geräuschquelle zu zeichnen.","m":"Papier, Stift","f":"Welche Linie lässt sich hören, obwohl sie stumm ist?"},
  {"id":"027","n":"Tasten ohne Schauen","t":"Raum & Material","nb":["Form"],"v":0,"s":1,"d":8,"a":"Ertaste drei ungefährliche kleine Gegenstände mit geschlossenen Augen und zeichne danach nur Form und Textur aus der Erinnerung.","m":"3 sichere Gegenstände, Papier","f":"Was hat die Hand wahrgenommen, und wie unterscheidet sich das vom Sehen?"},
  {"id":"028","n":"Papiersorten","t":"Raum & Material","nb":[],"v":1,"s":0,"d":8,"a":"Sammle fünf Papiere und ordne sie nach Steifigkeit, Oberfläche und Lichtdurchlässigkeit.","m":"verschiedene Papiere","f":"Welche Eigenschaft bestimmt am stärksten, was du damit machen möchtest?"},
  {"id":"029","n":"Natur / gemacht","t":"Form","nb":[],"v":0,"s":0,"d":12,"a":"Sammle je fünf natürliche und hergestellte Formen und suche danach zwei, die sich formal stark ähneln.","m":"Umgebung, Kamera/Skizzenbuch","f":"Welches Paar macht die Unterscheidung natur/gemacht überraschend unwichtig?"},
  {"id":"030","n":"Farbgedächtnis","t":"Farbe","nb":["Zeit & Körper"],"v":0,"s":1,"d":8,"a":"Betrachte 20 Sekunden lang eine Farbe, wende dich ab und mische oder wähle aus mehreren Tönen die erinnerte Farbe.","m":"Farbmaterial oder digitale Farbwahl","f":"War deine Erinnerung heller, dunkler, wärmer oder kühler?"},
  {"id":"031","n":"Detail vergrößern","t":"Form","nb":[],"v":0,"s":0,"d":12,"a":"Wähle einen sehr kleinen Ausschnitt eines Gegenstands oder Bildes und vergrößere ihn, bis er das ganze Format füllt.","m":"Vorlage, Papier, Zeichenmittel","f":"Erkennst du den Ausschnitt noch als Teil des Originals? Ab wann nicht mehr?"},
  {"id":"032","n":"Komplexes verkleinern","t":"Form","nb":[],"v":0,"s":1,"d":12,"a":"Wähle ein Motiv mit vielen Einzelteilen (zum Beispiel einen Baum, ein Gesicht oder ein Foto). Zeichne es dreimal nacheinander mit immer weniger Formen: zuerst aus zehn Formen, dann aus fünf, dann aus drei. Jede Fassung entsteht aus der vorherigen, indem du Formen weglässt oder zusammenfasst.","m":"Vorlage, Papier","f":"Welche Form musste bleiben, damit das Motiv zusammenhielt?"},
  {"id":"033","n":"Drehen","t":"Form","nb":["Linie"],"v":1,"s":0,"d":8,"a":"Drehe eine vorhandene Zeichnung um 90°, 180° und 270° und ergänze in jeder Lage genau eine Form.","m":"Zeichnung, Stift","f":"In welcher Lage ergab sich die Fortsetzung am leichtesten, in welcher am schwersten?"},
  {"id":"034","n":"Spiegeln","t":"Form","nb":[],"v":0,"s":0,"d":10,"a":"Übertrage eine einfache Komposition gespiegelt und verändere anschließend nur ein Element.","m":"Vorlage, Papier","f":"Was verändert sich, obwohl fast alles gleich geblieben ist?"},
  {"id":"035","n":"Neu rahmen","t":"Form","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":10,"a":"Wähle aus einer vorhandenen Arbeit drei unterschiedliche Ausschnitte und behandle jeden als eigenständige Komposition.","m":"eigene Arbeit, Papierrahmen/Kamera","f":"Welcher Ausschnitt wirkt vollständiger als das ganze Bild?"},
  {"id":"036","n":"Figur wird Grund","t":"Form","nb":["Raum & Material"],"v":0,"s":1,"d":10,"a":"Zeichne eine einfache Form und gestalte anschließend nicht die Form, sondern nur den Raum um sie herum.","m":"Papier, Zeichen-/Farbmittel","f":"Wann beginnt der Leerraum selbst als Figur zu wirken?"},
  {"id":"037","n":"Palette tauschen","t":"Farbe","nb":[],"v":1,"s":1,"d":15,"a":"Übertrage eine kleine bestehende Arbeit mit vollständig anderer Farbpalette, ohne Formen zu verändern.","m":"Vorlage, Farbmittel","f":"Was verändert die Farbe, obwohl die Form identisch bleibt?"},
  {"id":"038","n":"Gleiche Farbe, andere Nachbarschaft","t":"Farbe","nb":[],"v":0,"s":1,"d":12,"a":"Setze zwei identische Farbfelder auf deutlich verschiedene Hintergründe und suche Kontexte, in denen sie möglichst verschieden erscheinen.","m":"Farbpapier oder digitale Flächen","f":"Wie verändert die Hintergrundfarbe die identische Farbe – bei welchem Hintergrund am stärksten, bei welchem kaum?"},
  {"id":"039","n":"Nachbild","t":"Farbe","nb":["Zeit & Körper"],"v":0,"s":0,"d":5,"a":"Betrachte längere Zeit eine kräftige Farbfläche und wechsle dann auf eine helle neutrale Fläche. Beobachte das entstehende Nachbild.","m":"Farbfläche, helle Fläche","f":"Welche Farbe erscheint im Nachbild, und wie deutlich?"},
  {"id":"040","n":"Farbgradient","t":"Farbe","nb":[],"v":0,"s":1,"d":12,"a":"Erzeuge zwischen zwei gewählten Farben mindestens sieben Zwischenschritte – gemischt oder durch Auswahl vorhandener Töne.","m":"Farbe/Farbpapier oder digital","f":"Wo nimmst du die Stufen als gleichmäßig wahr, wo als Sprung?"},
  {"id":"041","n":"Vier Farben – vier Welten","t":"Farbe","nb":["Form"],"v":0,"s":1,"d":18,"a":"Verwende dieselben vier Farben in vier kleinen Kompositionen, ändere nur Menge und Platzierung.","m":"vier Farben/Farbpapiere","f":"Wie unterscheiden sich die vier Ergebnisse, obwohl die Farben identisch sind – oder kaum?"},
  {"id":"042","n":"Bild als Farbfelder","t":"Form","nb":["Farbe"],"v":0,"s":1,"d":20,"a":"Wähle ein Bild und übertrage es nur als wenige ausgeschnittene Farb- und Formflächen, ohne Details nachzuzeichnen.","m":"Bildvorlage, Farbpapier, Schere","f":"Welche wenigen Farbfelder tragen die größte Ähnlichkeit?"},
  {"id":"043","n":"Drei Abstraktionsstufen","t":"Form","nb":[],"v":0,"s":1,"d":18,"a":"Zeichne einen Gegenstand beobachtend, vereinfache ihn in einer zweiten Version und reduziere ihn in einer dritten auf Zeichen/Flächen.","m":"Objekt, Papier","f":"Welche Stufe sagt mit den wenigsten Mitteln am meisten?"},
  {"id":"044","n":"Fünf Formen reichen","t":"Form","nb":["Raum & Material"],"v":0,"s":1,"d":15,"a":"Übersetze ein Motiv in höchstens fünf ausgeschnittene Formen.","m":"Papier, Schere, Kleber","f":"Welche Form trägt die Komposition am stärksten, welche am wenigsten?"},
  {"id":"045","n":"Linie wird Fläche","t":"Form","nb":["Linie"],"v":0,"s":1,"d":15,"a":"Nimm eine Linienzeichnung und verwandle jede geschlossene Zone in eine ausgeschnittene oder gemalte Fläche.","m":"Linienzeichnung, Papier/Farbe","f":"Wo hat die Fläche etwas erzeugt, das die Linie nicht hatte?"},
  {"id":"046","n":"2D wird 3D","t":"Raum & Material","nb":["Linie"],"v":0,"s":1,"d":15,"a":"Zeichne eine einfache Linie und baue sie anschließend mit Draht, Schnur oder Papierstreifen als räumliche Linie nach.","m":"Papier, Draht/Schnur/Papierstreifen","f":"Was muss eine Linie können, wenn sie plötzlich im Raum steht?"},
  {"id":"047","n":"Eine Fläche wird Raum","t":"Raum & Material","nb":["Form"],"v":0,"s":1,"d":20,"a":"Verwandle ein einziges Blatt durch Falten, Schneiden und Stecken in eine stehende dreidimensionale Struktur.","m":"ein Blatt Papier, Schere","f":"Welche Veränderung gibt dem flachen Material die größte räumliche Stabilität?"},
  {"id":"048","n":"Material imitiert Material","t":"Raum & Material","nb":[],"v":0,"s":1,"d":15,"a":"Versuche mit einem Material die Oberflächenwirkung eines anderen zu erzeugen, z. B. Papier wie Rinde oder Metall wie Stoff erscheinen zu lassen.","m":"2 Materialien als Referenz, 1 Arbeitsmaterial","f":"Was musstest du am Material anpassen, damit es als ein anderes erscheint?"},
  {"id":"049","n":"Gegenqualität","t":"Raum & Material","nb":[],"v":0,"s":1,"d":15,"a":"Nimm ein Material und gestalte es so, dass es möglichst gegensätzlich zu seiner üblichen Wirkung erscheint: weich/hart, leicht/schwer, ruhig/unruhig.","m":"ein Material","f":"Welche Eigenschaft des Materials ließ sich nicht überreden?"},
  {"id":"050","n":"Zerschneiden und neu ordnen","t":"Form","nb":["Raum & Material"],"v":1,"s":0,"d":15,"a":"Zerschneide eine eigene Zeichnung in mindestens acht Teile und ordne sie zu einer neuen Komposition.","m":"eigene Zeichnung, Schere","f":"Was bleibt vom ursprünglichen Bild erhalten, obwohl die Ordnung zerstört ist?"},
  {"id":"051","n":"Zufallsordnung","t":"Zufall","nb":["Form"],"v":0,"s":0,"d":10,"a":"Lass kleine Papierformen fallen, fixiere ihre zufällige Lage zunächst gedanklich und verändere anschließend nur drei Positionen bewusst.","m":"Papierformen","f":"Welche deiner drei Entscheidungen hatte die größte kompositorische Wirkung?"},
  {"id":"052","n":"Automatische Linie – bewusste Form","t":"Zufall","nb":["Linie"],"v":0,"s":0,"d":10,"a":"Führe eine Linie schnell und ohne Motivplanung über das Blatt. Suche danach zwei interessante Bereiche und arbeite nur dort weiter.","m":"Papier, Stift","f":"Was wurde erst durch deine spätere Auswahl zur Form?"},
  {"id":"053","n":"Blind beginnen, sehend fortsetzen","t":"Zufall","nb":["Linie"],"v":0,"s":0,"d":10,"a":"Beginne eine Zeichnung ohne aufs Papier zu schauen. Danach sieh hin und ergänze nur drei bewusste Eingriffe.","m":"Objekt, Papier, Stift","f":"Gibt es unbeabsichtigte Stellen, die du erhalten möchtest? Welche und warum?"},
  {"id":"054","n":"Abdruck und Spiegelung","t":"Form","nb":["Raum & Material"],"v":0,"s":1,"d":18,"a":"Erzeuge einen einfachen Druck oder Abdruck und vergleiche ihn mit der Druckplatte bzw. Ausgangsform. Ergänze im Abdruck eine neue Form.","m":"Schaumplatte/Stempel/Monoprintmaterial","f":"Was hat sich durch den Druck an Richtung oder Form verändert – oder blieb es gleich?"},
  {"id":"055","n":"Frottage wird Landschaft","t":"Raum & Material","nb":["Form"],"v":0,"s":0,"d":15,"a":"Erzeuge drei Frottagen verschiedener Oberflächen, schneide sie aus und kombiniere sie zu einer neuen nichtgegenständlichen Fläche.","m":"Papier, weicher Stift, Oberflächen, Schere","f":"Welche ursprüngliche Oberfläche ist in der neuen Ordnung noch erkennbar?"},
  {"id":"056","n":"Ein Motiv – drei Medien","t":"Form","nb":["Raum & Material"],"v":0,"s":1,"d":25,"a":"Setze dasselbe einfache Motiv als Zeichnung, Collage und räumliche Miniatur um.","m":"Papier, Stift, Collagematerial, einfaches Baumaterial","f":"Welche Eigenschaft des Motivs überlebt jeden Medienwechsel?"},
  {"id":"057","n":"Transparente Schichten","t":"Form","nb":["Farbe","Raum & Material"],"v":0,"s":1,"d":15,"a":"Zeichne oder male zwei einfache Strukturen auf transparente/semitransparente Träger und untersuche verschiedene Überlagerungen.","m":"Transparentpapier/Folie, Stifte/Farbe","f":"Welche neue Form existiert nur durch die Überlagerung?"},
  {"id":"058","n":"Raster verzerren","t":"Form","nb":["Raum & Material"],"v":0,"s":1,"d":18,"a":"Übertrage ein einfaches Motiv mit Hilfe eines Rasters und verändere im Zielraster Breite oder Höhe einzelner Felder.","m":"Vorlage, Papier, Lineal","f":"Wo kippt Wiedererkennbarkeit in Verfremdung?"},
  {"id":"059","n":"Drei Zustände","t":"Zeit & Körper","nb":["Form"],"v":0,"s":0,"d":15,"a":"Gestalte dieselbe Form als vorher – während – nachher, ohne eine Geschichte zu erklären.","m":"Papier, Zeichen-/Farbmittel","f":"Welche minimale Veränderung erzeugt den stärksten Eindruck von Zeit?"},
  {"id":"060","n":"Rest wird Ausgangspunkt","t":"Zufall","nb":["Farbe","Raum & Material"],"v":1,"s":0,"d":12,"a":"Nimm einen Verschnitt, Farbfleck, Kleberest oder Papierrest aus einer früheren Arbeit und mache ihn zum Ausgangspunkt einer neuen Miniatur.","m":"Materialreste","f":"Wann hörte der Rest auf, Rest zu sein?"},
  {"id":"061","n":"Drei Farben","t":"Farbe","nb":[],"v":0,"s":0,"d":12,"a":"Gestalte eine kleine Komposition mit genau drei Farben. Kein vierter Ton darf hinzukommen.","m":"Farbmittel/Farbpapier","f":"Welche Farbe übernimmt die größte Rolle – wegen Menge oder Position?"},
  {"id":"062","n":"Nur eine Form","t":"Form","nb":[],"v":0,"s":0,"d":15,"a":"Wähle eine einzige Grundform und entwickle daraus eine Komposition nur durch Wiederholung, Größe, Drehung und Überlagerung.","m":"Papier, Schere oder Zeichenmittel","f":"Welche Veränderung erzeugt Vielfalt, ohne die Grundform zu verlieren?"},
  {"id":"063","n":"Linienkomposition","t":"Linie","nb":["Form"],"v":0,"s":0,"d":15,"a":"Baue eine Komposition nur aus Linien und entscheide bewusst über Richtung, Abstand, Schichtung und Dichte.","m":"Papier, Stifte/Klebeband","f":"Wo beginnt eine Gruppe von Linien als Fläche zu wirken?"},
  {"id":"064","n":"Geometrisch oder organisch","t":"Form","nb":[],"v":0,"s":0,"d":12,"a":"Entscheide dich vor Beginn: nur geometrische oder nur organische Formen. Halte die Regel bis zum Ende.","m":"Papier, Zeichen-/Farbmittel","f":"Was vermisst du durch die gewählte Einschränkung?"},
  {"id":"065","n":"Offen oder geschlossen","t":"Form","nb":["Linie"],"v":0,"s":0,"d":10,"a":"Arbeite ausschließlich mit offenen oder ausschließlich mit geschlossenen Formen.","m":"Papier, Stift","f":"Wann entsteht trotz offener Linie eine geschlossene Form?"},
  {"id":"066","n":"Symmetrie mit einem Fehler","t":"Form","nb":[],"v":0,"s":0,"d":15,"a":"Baue eine symmetrische Komposition und durchbrich sie an genau einer Stelle.","m":"Papier, Zeichen-/Collagematerial","f":"Wie klein kann die Störung werden, bevor sie nicht mehr auffällt?"},
  {"id":"067","n":"Asymmetrisches Gleichgewicht","t":"Form","nb":[],"v":0,"s":1,"d":12,"a":"Verteile drei sehr unterschiedliche Formen so, dass die Komposition ausgewogen wirkt, ohne symmetrisch zu sein.","m":"Papier, Formen/Objekte","f":"Welche Form wiegt visuell mehr als ihre Größe vermuten lässt?"},
  {"id":"068","n":"Mitte vermeiden","t":"Form","nb":["Raum & Material"],"v":0,"s":0,"d":12,"a":"Gestalte eine Komposition, in der kein wichtiges Element die geometrische Mitte berührt.","m":"Papier, beliebiges Material","f":"Wo befindet sich das visuelle Zentrum, wenn es nicht in der Mitte liegt?"},
  {"id":"069","n":"Ein Hauptdarsteller","t":"Form","nb":[],"v":0,"s":0,"d":12,"a":"Entscheide, welches Element eindeutig dominant sein soll, und ordne alle anderen diesem unter.","m":"Papier, Formen/Farbe","f":"Wodurch dominiert das Hauptelement tatsächlich?"},
  {"id":"070","n":"Kippfigur","t":"Form","nb":[],"v":0,"s":1,"d":15,"a":"Baue mit zwei Formen oder zwei Tonwerten eine Figur-Grund-Situation, bei der beide Lesarten möglich bleiben.","m":"Papier, Schwarz/Weiß","f":"Wann kippt dein Blick von der einen in die andere Lesart?"},
  {"id":"071","n":"Halb leer","t":"Form","nb":["Raum & Material"],"v":0,"s":0,"d":12,"a":"Lass mindestens die Hälfte des Formats vollständig ungestaltet und konzentriere alle Eingriffe auf den Rest.","m":"Papier, beliebiges Medium","f":"Ist die leere Fläche passiv – oder gestaltet sie mit?"},
  {"id":"072","n":"Dichtegradient","t":"Form","nb":["Linie"],"v":0,"s":0,"d":12,"a":"Erzeuge einen kontinuierlichen Übergang von sehr dicht zu fast leer, ohne die Art der Elemente zu wechseln.","m":"Papier, Stift/Formelemente","f":"Wo genau wird aus dicht 'leer genug'?"},
  {"id":"073","n":"Rhythmus","t":"Zeit & Körper","nb":["Form"],"v":0,"s":0,"d":12,"a":"Wiederhole ein Element mindestens zwölfmal und entscheide über einen klaren visuellen Rhythmus.","m":"Papier, Stempel/Formen","f":"Wodurch entsteht der Rhythmus: Abstand, Größe, Richtung oder etwas anderes?"},
  {"id":"074","n":"Regel wird unregelmäßig","t":"Zeit & Körper","nb":["Form"],"v":0,"s":0,"d":12,"a":"Beginne mit einer streng regelmäßigen Folge und lasse sie schrittweise unregelmäßig werden.","m":"Papier, Formelemente","f":"Ab welchem Schritt erkennst du die ursprüngliche Regel nicht mehr sofort?"},
  {"id":"075","n":"Drei Größen","t":"Form","nb":[],"v":0,"s":0,"d":12,"a":"Verwende eine Form ausschließlich in drei festgelegten Größen: klein, mittel, groß.","m":"Papier, Formen","f":"Welche Größe strukturiert die anderen?"},
  {"id":"076","n":"Proportion 1–2–4","t":"Form","nb":[],"v":0,"s":1,"d":15,"a":"Arbeite mit drei Elementgrößen im ungefähren Verhältnis 1:2:4 und finde eine ausgewogene Verteilung.","m":"Papier, Formen","f":"Wirkt das Verhältnis geordnet oder spannungsreich?"},
  {"id":"077","n":"Nur zwei Materialien","t":"Raum & Material","nb":[],"v":0,"s":0,"d":15,"a":"Wähle zwei Materialien mit deutlich unterschiedlichen Eigenschaften und erlaube dir kein drittes.","m":"2 Materialien","f":"Welche Beziehung entsteht gerade aus der Begrenzung auf zwei?"},
  {"id":"078","n":"Ohne Klebstoff","t":"Raum & Material","nb":[],"v":0,"s":1,"d":20,"a":"Baue eine kleine stabile Struktur ohne Klebstoff. Verbindungen dürfen nur durch Stecken, Falten, Klemmen, Druck oder Balance entstehen.","m":"Papier/Karton/geeignete Materialien","f":"Welche Verbindung ist zugleich einfach und stabil?"},
  {"id":"079","n":"Nur Balance und Druck","t":"Raum & Material","nb":[],"v":0,"s":1,"d":15,"a":"Verbinde mehrere Teile so, dass sie ausschließlich durch Eigengewicht, Druck oder Spannung zusammenhalten.","m":"geeignete leichte Materialien","f":"Wo arbeitet die Schwerkraft für deine Form statt gegen sie?"},
  {"id":"080","n":"Eine klare Idee","t":"Form","nb":["Raum & Material"],"v":1,"s":1,"d":18,"a":"Nimm nur ein Material und formuliere vor Beginn eine einzige formale Idee, z. B. 'aufsteigen', 'fächern', 'verdichten'. Alles muss dieser Idee dienen.","m":"ein Material","f":"Welcher Eingriff trägt die Idee – und welcher wäre nur Dekoration?"},
  {"id":"081","n":"Zehn Schnitte","t":"Form","nb":["Raum & Material"],"v":0,"s":1,"d":12,"a":"Du hast genau zehn Schnitte, um aus einem Blatt eine eigenständige Komposition zu entwickeln.","m":"Papier, Schere","f":"Welcher Schnitt war nicht rückgängig zu machen und deshalb entscheidend?"},
  {"id":"082","n":"Keine Gerade","t":"Form","nb":["Linie"],"v":0,"s":0,"d":12,"a":"Gestalte eine klar gegliederte Komposition, ohne eine einzige gerade Linie zu verwenden.","m":"Papier, Stift/Farbe","f":"Wie erzeugst du Ordnung ohne Geraden?"},
  {"id":"083","n":"Keine Kurve","t":"Form","nb":["Linie"],"v":0,"s":0,"d":12,"a":"Gestalte eine bewegte Komposition ausschließlich mit Geraden und Winkeln.","m":"Papier, Stift/Farbe","f":"Welche Winkel erzeugen die stärkste Bewegung?"},
  {"id":"084","n":"Eine durchgehende Linie","t":"Linie","nb":["Form","Raum & Material"],"v":0,"s":0,"d":10,"a":"Gestalte ein ganzes Format mit einer einzigen ununterbrochenen Linie. Überkreuzungen sind erlaubt.","m":"Papier, Stift","f":"Wo wird die Linie zum Raum oder zur Fläche?"},
  {"id":"085","n":"Nur Schwarz und Weiß","t":"Raum & Material","nb":["Farbe","Form"],"v":0,"s":0,"d":15,"a":"Erzeuge mit ausschließlich Schwarz und Weiß eine Komposition mit möglichst vielfältiger räumlicher Wirkung.","m":"Papier, schwarze Farbe/Stift","f":"Wie viel Raum kann ohne Grau entstehen?"},
  {"id":"086","n":"Fünf Grauwerte","t":"Farbe","nb":[],"v":0,"s":1,"d":15,"a":"Lege fünf klar unterscheidbare Grauwerte fest und verwende ausschließlich diese.","m":"Papier, Bleistift/Grauwerte","f":"Welcher Wert verbindet – welcher trennt?"},
  {"id":"087","n":"Komplementärpaar","t":"Farbe","nb":[],"v":0,"s":0,"d":15,"a":"Arbeite ausschließlich mit einem Komplementärpaar plus Weiß/Grund.","m":"Farbmittel","f":"Wo beginnen die beiden Farben miteinander zu 'vibrieren'?"},
  {"id":"088","n":"Nachbarfarben","t":"Farbe","nb":["Raum & Material"],"v":0,"s":1,"d":15,"a":"Wähle drei bis fünf benachbarte Farbtöne und erzeuge Tiefe ausschließlich durch Menge, Helligkeit und Position.","m":"Farbmittel","f":"Wie viel Raumwirkung erzeugen kleine Differenzen zwischen den Nachbarfarben?"},
  {"id":"089","n":"Gleiche Farben – ungleiche Mengen","t":"Farbe","nb":[],"v":0,"s":1,"d":15,"a":"Verwende vier Farben; eine darf nur sehr wenig, eine sehr viel, zwei mittel vorkommen. Verändere anschließend nur die Mengenverhältnisse.","m":"vier Farben","f":"Welche Farbe wird durch geringe Menge stärker statt schwächer?"},
  {"id":"090","n":"Stoppregel","t":"Zufall","nb":["Zeit & Körper"],"v":0,"s":0,"d":8,"a":"Lege vor Beginn eine eindeutige Stoppregel fest, z. B. nach 20 Strichen, 12 Teilen oder 8 Minuten. Beende die Arbeit dann wirklich.","m":"beliebiges Material","f":"Was bleibt offen, weil die Regel stärker war als dein Wunsch weiterzumachen?"},
  {"id":"091","n":"Blindkontur","t":"Linie","nb":["Zeit & Körper"],"v":0,"s":0,"d":8,"a":"Wähle einen Gegenstand. Folge seiner Kontur sehr langsam mit den Augen und zeichne gleichzeitig, ohne aufs Papier zu sehen und ohne den Stift abzusetzen.","m":"Objekt, Papier, Stift","f":"Wie genau ist die Zeichnung im Vergleich zu deiner Erwartung?"},
  {"id":"092","n":"Langsame Kontur","t":"Linie","nb":["Zeit & Körper"],"v":0,"s":0,"d":10,"a":"Zeichne die Kontur eines Gegenstands so langsam, dass Auge und Hand möglichst gleichzeitig entlangwandern. Auf das Papier darfst du schauen.","m":"Objekt, Papier, Stift","f":"Wo wolltest du schneller werden als dein Blick?"},
  {"id":"093","n":"30-Sekunden-Geste","t":"Zeit & Körper","nb":["Linie"],"v":0,"s":0,"d":5,"a":"Zeichne ein Objekt oder eine Pose in 30 Sekunden nur als Bewegungs- und Richtungsstruktur. Wiederhole fünfmal.","m":"Objekt/Pose, Papier, Stift","f":"Welche Information bleibt übrig, wenn für Details keine Zeit ist?"},
  {"id":"094","n":"Ungewohnte Hand","t":"Linie","nb":["Zeit & Körper"],"v":0,"s":0,"d":8,"a":"Zeichne dasselbe einfache Motiv zuerst mit der gewohnten, dann mit der ungewohnten Hand.","m":"Objekt, Papier, Stift","f":"Welche Linienqualität entsteht nur durch die geringere Kontrolle?"},
  {"id":"095","n":"Ohne Absetzen","t":"Linie","nb":["Zeit & Körper"],"v":0,"s":0,"d":5,"a":"Zeichne fünf Minuten lang, ohne den Stift vom Papier zu heben. Motivwahl ist frei.","m":"Papier, Stift","f":"Wie hat die Regel deine Verbindungen beeinflusst?"},
  {"id":"096","n":"Große Schulterlinie","t":"Zeit & Körper","nb":["Linie"],"v":0,"s":0,"d":8,"a":"Arbeite auf möglichst großem Papier und zeichne Linien aus Schulter und Arm statt aus Fingern und Handgelenk.","m":"großes Papier, weiches Zeichenmittel","f":"Welche Bewegung sieht man der Linie noch an?"},
  {"id":"097","n":"Druckskala","t":"Farbe","nb":["Linie"],"v":0,"s":0,"d":6,"a":"Erzeuge mit demselben Stift zehn Linien von möglichst leicht bis möglichst kräftig, ohne die Linienbreite bewusst zu ändern.","m":"Papier, Bleistift/Kreide","f":"Wo beginnt Druck als Tonwert zu wirken?"},
  {"id":"098","n":"Ein Pinsel – fünf Spuren","t":"Linie","nb":["Raum & Material"],"v":0,"s":0,"d":10,"a":"Finde mit demselben Pinsel fünf möglichst unterschiedliche Spuren: Spitze, Seite, trocken, nass, gedreht usw.","m":"Pinsel, Farbe, Papier","f":"Welche Spur widerspricht am stärksten deiner Vorstellung davon, was ein Pinsel 'macht'?"},
  {"id":"099","n":"Werkzeugtausch","t":"Linie","nb":["Raum & Material"],"v":0,"s":0,"d":12,"a":"Trage Farbe nicht mit einem Pinsel, sondern nacheinander mit Karte, Schwamm, Stäbchen oder anderem ungefährlichem Werkzeug auf.","m":"Farbe, Papier, alternative Werkzeuge","f":"Welches Werkzeug erzeugt die reichste Spur mit dem kleinsten Eingriff?"},
  {"id":"100","n":"Finger als Werkzeug","t":"Raum & Material","nb":["Form","Zeit & Körper"],"v":0,"s":0,"d":10,"a":"Erzeuge eine kleine Tonwert- oder Texturfläche ausschließlich mit Fingerabdrücken.","m":"ungiftige Farbe/Stempelkissen, Papier","f":"Wann wird der einzelne Abdruck zur Fläche?"},
  {"id":"101","n":"Durchkratzen","t":"Raum & Material","nb":["Farbe","Linie"],"v":0,"s":1,"d":15,"a":"Lege zwei unterschiedlich gefärbte Schichten an und kratze nach dem Trocknen Linien oder Flächen aus der oberen Schicht.","m":"geeignete ungiftige Farben/Kreiden, Kratzwerkzeug","f":"Ist die freigelegte Spur eher Linie, Farbe oder Materialereignis?"},
  {"id":"102","n":"Schwerkraftspur","t":"Zufall","nb":["Farbe","Linie"],"v":0,"s":0,"d":12,"a":"Setze flüssige Farbe am Rand einer Fläche an und lass ausschließlich die Schwerkraft die erste Bewegung bestimmen. Drehe den Träger höchstens dreimal.","m":"flüssige Farbe/Tinte, Papier","f":"Welche Entscheidung war wichtiger: der Tropfen oder das Drehen?"},
  {"id":"103","n":"Punkt für Punkt","t":"Form","nb":["Linie"],"v":0,"s":0,"d":15,"a":"Baue eine Form oder Fläche ausschließlich aus Punkten auf und variiere nur Abstand, Größe und Dichte.","m":"Papier, Stifte/Farbe","f":"Wann verbinden sich einzelne Punkte optisch zu einer Fläche?"},
  {"id":"104","n":"Schaumplattendruck","t":"Form","nb":["Farbe","Raum & Material"],"v":0,"s":1,"d":20,"a":"Ritze eine einfache Form in weiches Druckmaterial, rolle Farbe auf und drucke mindestens zwei Varianten.","m":"Schaumdruckplatte, Stift, Druckfarbe, Papier, Walze/Farbroller","f":"Was ist im Druck anders als in der Platte?"},
  {"id":"105","n":"Gemaltes Papier collagieren","t":"Form","nb":["Farbe","Raum & Material"],"v":0,"s":1,"d":25,"a":"Male zunächst mehrere Papierflächen unterschiedlich, schneide sie danach in Formen und setze daraus eine neue Komposition zusammen.","m":"Papier, Farbe, Schere, Kleber","f":"Welche Spuren des Malens bleiben nach dem Schneiden wichtig?"},
  {"id":"106","n":"Geschnittene Formen","t":"Form","nb":["Raum & Material"],"v":0,"s":0,"d":18,"a":"Erzeuge eine Komposition hauptsächlich durch geschnittene statt gezeichnete Formen. Verschiebe sie mehrfach, bevor du fixierst.","m":"Farbpapier, Schere, Kleber optional","f":"Wie hat das wiederholte Verschieben die Platzierung der Formen verändert?"},
  {"id":"107","n":"Kartenwebrahmen","t":"Zeit & Körper","nb":["Raum & Material"],"v":0,"s":1,"d":25,"a":"Baue aus Karton einen kleinen einfachen Webrahmen und erzeuge ein Muster mit wenigen Fäden oder Papierstreifen.","m":"Karton, Faden/Papierstreifen, Schere","f":"Welche Ordnung entsteht allein durch das Über-und-Unter?"},
  {"id":"108","n":"Salzspur","t":"Linie","nb":["Raum & Material"],"v":0,"s":0,"d":12,"a":"Zeichne oder ordne Linien und Flächen mit Salz auf einem dunklen Untergrund und verändere sie mit einfachen Werkzeugen.","m":"Salz, dunkles Papier/Tablett, Löffel/Karte","f":"Was verändert sich, weil die Zeichnung jederzeit verschiebbar bleibt?"},
  {"id":"109","n":"Papier steht","t":"Raum & Material","nb":["Form"],"v":0,"s":1,"d":20,"a":"Verwandle ein einziges Blatt durch Falten, Einschnitte und Stecken in eine selbststehende Form. Kein Kleber.","m":"Papier/Karton, Schere","f":"Wo trägt das Papier sich selbst?"},
  {"id":"110","n":"Papier verzahnen","t":"Raum & Material","nb":["Form"],"v":0,"s":1,"d":20,"a":"Schneide mehrere Schlitze in Papierformen und verbinde sie durch Ineinanderstecken zu einer räumlichen Struktur.","m":"Papier/Karton, Schere","f":"Welche Steckung gibt mit dem wenigsten Material die meiste Stabilität?"},
  {"id":"111","n":"Ton: drücken, rollen, ziehen","t":"Raum & Material","nb":["Zeit & Körper"],"v":0,"s":0,"d":12,"a":"Erzeuge aus einem Stück Ton oder Knete mindestens sechs unterschiedliche Spuren bzw. Formveränderungen, ohne etwas Bestimmtes darstellen zu wollen.","m":"Ton/Knete, Unterlage","f":"Welche Bewegung beantwortet das Material am deutlichsten?"},
  {"id":"112","n":"Bauen – verändern – bauen","t":"Form","nb":["Raum & Material"],"v":0,"s":1,"d":18,"a":"Baue aus Ton/Knete eine einfache Form, verändere sie radikal und entwickle aus dem veränderten Zustand eine zweite stabile Form.","m":"Ton/Knete","f":"Was aus der ersten Form blieb in der zweiten erhalten?"},
  {"id":"113","n":"Fundstück-Assemblage","t":"Raum & Material","nb":[],"v":1,"s":1,"d":20,"a":"Verbinde fünf gefundene ungefährliche Materialien zu einer kleinen Struktur. Mindestens zwei Verbindungen müssen ohne Kleber funktionieren.","m":"Fundmaterialien, optional Schnur/Klammern","f":"Welche Verbindung wirkt materialgerecht statt nur praktisch?"},
  {"id":"114","n":"Frottage-Serie","t":"Raum & Material","nb":["Linie"],"v":0,"s":0,"d":12,"a":"Erzeuge von derselben Oberfläche vier Frottagen mit unterschiedlichen Stiften, Druckstärken oder Papieren.","m":"Papier, weiche Zeichenmittel, Oberfläche","f":"Welche Kombination macht die Oberfläche am sichtbarsten?"},
  {"id":"115","n":"Monoprint aus Restfarbe","t":"Linie","nb":["Farbe","Raum & Material"],"v":0,"s":1,"d":18,"a":"Verteile dünn Farbe auf einer glatten ungefährlichen Platte, zeichne/entferne darin Spuren und drucke einmalig auf Papier.","m":"ungiftige Farbe, glatte Platte, Papier","f":"Welche Spur gehört der Platte und welche erst dem Druck?"},
  {"id":"116","n":"Schablone: positiv / negativ","t":"Form","nb":["Farbe","Raum & Material"],"v":0,"s":0,"d":18,"a":"Schneide eine einfache Schablone und nutze sowohl die ausgeschnittene Form als auch das Loch für zwei gegensätzliche Abdrücke.","m":"Papier/Karton, Schere, Farbe","f":"Welche Version liest sich schneller als Figur?"},
  {"id":"117","n":"Nass / trocken","t":"Raum & Material","nb":["Farbe"],"v":0,"s":0,"d":12,"a":"Erzeuge mit derselben Farbe je eine Fläche nass-in-nass und eine mit möglichst trockenem Werkzeug. Vergleiche die Ränder und Texturen.","m":"Aquarell/Gouache o. Ä., Papier, Pinsel","f":"Wo entscheidet das Wasser stärker als deine Hand?"},
  {"id":"118","n":"Schicht über Schicht","t":"Farbe","nb":["Raum & Material"],"v":0,"s":1,"d":15,"a":"Lege drei transparente oder halbtransparente Schichten übereinander und plane, wo neue Mischfarben oder Verdichtungen entstehen.","m":"Lasur/Farbfolie/Transparentpapier","f":"Welche Farbe oder Form existiert erst durch die Überlagerung?"},
  {"id":"119","n":"30 Sekunden – 3 Minuten – 10 Minuten","t":"Zeit & Körper","nb":["Form"],"v":0,"s":0,"d":15,"a":"Setze dasselbe Motiv dreimal um: sehr kurz, mittel und langsam. Verwende dasselbe Werkzeug.","m":"Objekt, Papier, Zeichenmittel","f":"Was kommt erst mit Zeit hinzu – und was geht dabei verloren?"},
  {"id":"120","n":"Zwölf Variationen","t":"Form","nb":["Zeit & Körper"],"v":0,"s":1,"d":20,"a":"Erzeuge zwölf sehr kleine Versionen derselben Ausgangsform; jede darf sich nur in einem Merkmal verändern.","m":"Papier, Zeichen-/Collagemittel","f":"Welche kleine Veränderung hat die größte Wirkung?"},
  {"id":"121","n":"Nur sehen","t":"Symbol & Würdigung","nb":[],"v":1,"s":0,"d":5,"a":"Betrachte deine Arbeit eine Minute und notiere fünf rein sichtbare Tatsachen, ohne Bedeutung oder Bewertung.","m":"eigene Arbeit, Papier optional","f":"Welche Tatsache hattest du beim Machen nicht bemerkt?"},
  {"id":"122","n":"Zweites Sehen","t":"Zeit & Körper","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":5,"a":"Notiere beim ersten Blick fünf Dinge. Schau 30 Sekunden weiter und finde danach fünf neue Beobachtungen, die vorher fehlten.","m":"eigene Arbeit","f":"Was hat sich durch längeres Sehen verändert – oder nichts?"},
  {"id":"123","n":"Farbe – Form – Linie","t":"Symbol & Würdigung","nb":["Farbe","Form"],"v":1,"s":0,"d":5,"a":"Beschreibe die Arbeit nacheinander nur unter drei Aspekten: Farben, Formen, Linien.","m":"eigene Arbeit","f":"Welche Kategorie erzählt am meisten über die Arbeit?"},
  {"id":"124","n":"Erster Blick / zweiter Blick","t":"Symbol & Würdigung","nb":[],"v":1,"s":0,"d":5,"a":"Halte deinen ersten Eindruck in drei Wörtern fest. Betrachte die Arbeit länger und ersetze danach mindestens eines der Wörter.","m":"eigene Arbeit","f":"Was hat sich zwischen erstem und zweitem Blick verändert, und was nicht?"},
  {"id":"125","n":"Überraschendste Stelle","t":"Zufall","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":5,"a":"Finde eine Stelle, die nicht vollständig geplant war und dennoch wichtig geworden ist. Markiere oder fotografiere sie.","m":"eigene Arbeit, Kamera optional","f":"Möchtest du diese Stelle behalten? Warum oder warum nicht?"},
  {"id":"126","n":"Blickmagnet","t":"Symbol & Würdigung","nb":["Linie"],"v":1,"s":0,"d":5,"a":"Beobachte, wohin dein Blick zuerst geht und wohin er danach wandert. Zeichne den Blickweg als Pfeile auf einer Kopie oder im Kopf nach.","m":"eigene Arbeit, optional Foto/Kopie","f":"Was zieht an – Größe, Kontrast, Farbe, Lage oder etwas anderes?"},
  {"id":"127","n":"Drei Distanzen","t":"Symbol & Würdigung","nb":["Raum & Material"],"v":1,"s":0,"d":5,"a":"Betrachte die Arbeit nah, aus normaler Distanz und möglichst weit entfernt. Notiere je eine Veränderung.","m":"eigene Arbeit","f":"Welche Distanz zeigt dir die Arbeit am klarsten?"},
  {"id":"128","n":"Gedreht betrachten","t":"Form","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":4,"a":"Drehe die Arbeit um 90°, 180° und 270°, ohne sie zu verändern.","m":"eigene Arbeit","f":"Welche Ausrichtung wirkt überraschend stabil?"},
  {"id":"129","n":"Eigenständiger Ausschnitt","t":"Symbol & Würdigung","nb":["Form"],"v":1,"s":0,"d":6,"a":"Suche mit einem Rahmen den stärksten kleinen Ausschnitt der Arbeit und dokumentiere ihn separat.","m":"eigene Arbeit, Papierrahmen/Kamera","f":"Was besitzt der Ausschnitt, das im Ganzen weniger sichtbar ist?"},
  {"id":"130","n":"Titel danach","t":"Symbol & Würdigung","nb":[],"v":1,"s":0,"d":4,"a":"Gib der Arbeit erst nach genauer Betrachtung einen kurzen Titel von höchstens vier Wörtern.","m":"eigene Arbeit","f":"Bezeichnet der Titel das Sichtbare oder verändert er dessen Lesart?"},
  {"id":"131","n":"Drei Verben","t":"Zeit & Körper","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":4,"a":"Beschreibe die Arbeit mit drei Verben statt mit Eigenschaftswörtern.","m":"eigene Arbeit","f":"Was tut die Arbeit, wenn du sie als Vorgang statt als Ding beschreibst?"},
  {"id":"132","n":"Fünf Formwörter","t":"Form","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":5,"a":"Finde fünf präzise formale Wörter, z. B. dicht, offen, geknickt, transparent, schwer – ohne 'schön' oder 'hässlich'.","m":"eigene Arbeit","f":"Welches Wort passt nur auf einen kleinen Teil und prägt trotzdem das Ganze?"},
  {"id":"133","n":"Wie wurde es gemacht?","t":"Symbol & Würdigung","nb":["Linie","Zeit & Körper"],"v":1,"s":1,"d":6,"a":"Betrachte die fertige Arbeit, als hättest du sie nicht selbst gemacht, und rekonstruiere fünf sichtbare Herstellungsschritte.","m":"eigene Arbeit","f":"Welche Arbeitsspur verrät am meisten über den Prozess?"},
  {"id":"134","n":"Drei Entscheidungen","t":"Zufall","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":5,"a":"Identifiziere drei Stellen, an denen eine konkrete Entscheidung sichtbar ist: Farbe, Schnitt, Richtung, Ende, Überlagerung …","m":"eigene Arbeit","f":"Welche Entscheidung war am folgenreichsten für alles Weitere?"},
  {"id":"135","n":"Drei Zufälle","t":"Zufall","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":5,"a":"Finde drei Stellen, die nicht vollständig geplant waren. Entscheide bei jeder: behalten, verändern oder neutral.","m":"eigene Arbeit","f":"Wann wird ein Zufall durch dein Behalten zur Entscheidung?"},
  {"id":"136","n":"Regelprüfung","t":"Form","nb":["Symbol & Würdigung","Zufall"],"v":1,"s":0,"d":5,"a":"Erinnere dich an die zentrale Einschränkung der Übung und suche drei Stellen, an denen sie die Arbeit sichtbar geprägt hat.","m":"eigene Arbeit","f":"Wo hat die Regel etwas ermöglicht, das ohne sie nicht entstanden wäre?"},
  {"id":"137","n":"Kontrastkarte","t":"Symbol & Würdigung","nb":["Form"],"v":1,"s":0,"d":5,"a":"Suche die drei stärksten Kontraste in der Arbeit und benenne jeweils, worin sie bestehen.","m":"eigene Arbeit","f":"Welcher Kontrast strukturiert das Ganze am stärksten?"},
  {"id":"138","n":"Rhythmuskarte","t":"Zeit & Körper","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":5,"a":"Suche Wiederholungen und markiere gedanklich oder auf einer Kopie ihre Folge und Unterbrechungen.","m":"eigene Arbeit, optional Kopie","f":"Wo wird Wiederholung zum Rhythmus – und wo nur zum Muster?"},
  {"id":"139","n":"Figur-Grund-Test","t":"Form","nb":["Symbol & Würdigung"],"v":1,"s":1,"d":5,"a":"Benenne, was du zuerst als Figur und was als Hintergrund liest. Versuche danach, diese Lesart bewusst umzukehren.","m":"eigene Arbeit","f":"Welche Bereiche lassen sich nicht eindeutig einer Seite zuordnen?"},
  {"id":"140","n":"Farbhierarchie","t":"Farbe","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":5,"a":"Ordne alle verwendeten Farben danach, wie stark sie deine Aufmerksamkeit beanspruchen – nicht danach, wie viel Fläche sie einnehmen.","m":"eigene Arbeit","f":"Welche kleine Farbfläche ist stärker als eine große?"},
  {"id":"141","n":"Fünf-Werte-Thumbnail","t":"Farbe","nb":["Form"],"v":1,"s":1,"d":8,"a":"Übertrage die Arbeit winzig klein nur in fünf Hell-Dunkel-Werten.","m":"eigene Arbeit, Papier, Bleistift","f":"Bleibt die Komposition ohne Farbe verständlich?"},
  {"id":"142","n":"Fünf Linien","t":"Linie","nb":["Form"],"v":1,"s":1,"d":6,"a":"Reduziere die Komposition nachträglich auf höchstens fünf Richtungs- oder Struktur-Linien.","m":"eigene Arbeit, Papier","f":"Welche Linie trägt die Gesamtbewegung?"},
  {"id":"143","n":"Zwei Versionen vergleichen","t":"Symbol & Würdigung","nb":["Form"],"v":1,"s":0,"d":6,"a":"Lege zwei Varianten derselben Aufgabe nebeneinander und notiere drei formale Unterschiede und eine unerwartete Gemeinsamkeit.","m":"zwei Arbeiten","f":"Welche Entscheidungen erklären die Unterschiede zwischen den Versionen?"},
  {"id":"144","n":"Nur eine Änderung","t":"Symbol & Würdigung","nb":["Zufall"],"v":1,"s":1,"d":5,"a":"Wähle nach der Betrachtung genau eine Veränderung, die du noch vornehmen darfst. Alles andere bleibt.","m":"eigene Arbeit, Material","f":"Warum ist genau diese eine Änderung wichtiger als alle anderen?"},
  {"id":"145","n":"Ein Element wegdenken","t":"Form","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":4,"a":"Stell dir vor, ein Element verschwände vollständig. Welches Weglassen würde die Komposition am stärksten verändern?","m":"eigene Arbeit","f":"Welches Element ist unverzichtbar, obwohl es vielleicht klein ist?"},
  {"id":"146","n":"Ein Element verdoppeln","t":"Raum & Material","nb":["Form","Symbol & Würdigung"],"v":1,"s":0,"d":4,"a":"Wähle ein Element und stell dir vor, es wäre ein zweites Mal vorhanden. Wo müsste es liegen, damit die Arbeit nicht kippt?","m":"eigene Arbeit","f":"Was würde die Wiederholung verstärken – und was zerstören?"},
  {"id":"147","n":"Ort wählen","t":"Symbol & Würdigung","nb":["Raum & Material"],"v":1,"s":0,"d":8,"a":"Probiere mindestens drei Orte oder Höhen aus, an denen die Arbeit liegen, stehen oder hängen könnte.","m":"eigene Arbeit","f":"An welchem Ort verändert die Umgebung die Arbeit am stärksten?"},
  {"id":"148","n":"Dokumentationsblick","t":"Symbol & Würdigung","nb":[],"v":1,"s":0,"d":8,"a":"Fotografiere die Arbeit aus drei leicht unterschiedlichen Distanzen oder Winkeln und wähle die sachlichste Dokumentation.","m":"eigene Arbeit, Kamera","f":"Welche Aufnahme zeigt die Arbeit statt eine Wirkung der Kamera?"},
  {"id":"149","n":"Rekonstruktionsanweisung","t":"Form","nb":["Raum & Material","Symbol & Würdigung"],"v":1,"s":1,"d":10,"a":"Schreibe eine kurze sachliche Anleitung, mit der jemand die sichtbare Struktur deiner Arbeit nachbauen könnte, ohne das Original zu sehen.","m":"eigene Arbeit, Papier","f":"Welche Eigenschaft lässt sich schwer in eine klare Operation übersetzen?"},
  {"id":"150","n":"Zurück in die Sammlung","t":"Zeit & Körper","nb":["Raum & Material","Symbol & Würdigung"],"v":1,"s":0,"d":4,"a":"Wähle aus der fertigen Arbeit ein Detail, eine Farbe, eine Linie oder ein Materialmerkmal, das zum Ausgangspunkt der nächsten Übung werden könnte.","m":"eigene Arbeit","f":"Was ist in dieser Arbeit entstanden, das eine nächste Arbeit verdient?"},
  {"id":"151","n":"Farbe und Wort getrennt","t":"Farbe","nb":["Symbol & Würdigung"],"v":0,"s":0,"d":10,"a":"Wähle drei Farben aus deiner Umgebung. Notiere zu jeder zuerst drei rein sichtbare Merkmale und erst danach drei kulturelle oder persönliche Assoziationen.","m":"Umgebung oder Farbmaterial, Papier","f":"Welche deiner Aussagen beschreibt wirklich die Farbe – und welche nur eine gelernte Bedeutung?"},
  {"id":"152","n":"Farbassoziationen sammeln","t":"Farbe","nb":["Symbol & Würdigung"],"v":0,"s":0,"d":10,"a":"Wähle ein neutrales Wort wie 'laut', 'nah', 'kühl' oder 'feierlich' und sammle fünf Farben, die für dich dazu passen. Suche danach bewusst eine sechste, die der Erwartung widerspricht.","m":"Farbmaterial oder digitale Farbauswahl","f":"Welche Farbe passt erst auf den zweiten Blick – und warum?"},
  {"id":"153","n":"Symbolfundstücke","t":"Symbol & Würdigung","nb":["Linie"],"v":0,"s":1,"d":12,"a":"Finde fünf Zeichen oder Symbole in deiner Umgebung. Zeichne sie ohne Erklärung ab und notiere anschließend je zwei mögliche Lesarten aus unterschiedlichen Kontexten.","m":"Umgebung, Papier, Stift","f":"Welches Symbol verändert seine Bedeutung am stärksten mit dem Kontext?"},
  {"id":"154","n":"Objekte ohne Funktion","t":"Form","nb":["Raum & Material"],"v":0,"s":0,"d":8,"a":"Wähle fünf Alltagsgegenstände ausschließlich nach Form, Material oder Oberfläche – ihre praktische Funktion soll bei der Auswahl keine Rolle spielen.","m":"Alltagsgegenstände","f":"Welcher Gegenstand wird am fremdesten, sobald du seine Funktion ausblendest?"},
  {"id":"155","n":"Materialeigenschaften statt Namen","t":"Raum & Material","nb":[],"v":0,"s":0,"d":10,"a":"Sammle sechs ungefährliche Materialien und beschreibe sie nur durch Eigenschaften wie biegsam, dicht, federnd, stumpf, kühl, saugend oder brüchig.","m":"verschiedene ungefährliche Materialien","f":"Welche Eigenschaft wird erst durch den direkten Umgang mit dem Material deutlich?"},
  {"id":"156","n":"Bewegungsqualitäten sehen","t":"Zeit & Körper","nb":["Symbol & Würdigung"],"v":0,"s":0,"d":8,"a":"Beobachte fünf alltägliche Bewegungen und ordne jeder eine neutrale Qualität zu: fließend, kantig, wirbelnd, leicht, langsam oder eine eigene Bezeichnung.","m":"Umgebung, Notiz/Skizzenbuch","f":"Welche Bewegung lässt sich am schwersten mit nur einem Wort fassen?"},
  {"id":"157","n":"Farbe gegen Erwartung","t":"Farbe","nb":["Symbol & Würdigung"],"v":0,"s":0,"d":12,"a":"Nimm eine Farbe, die du spontan mit einer bestimmten Eigenschaft verbindest, und gestalte dieselbe Eigenschaft anschließend mit einer gegensätzlichen Farbe.","m":"Farbmittel","f":"Was muss die Form leisten, wenn die erwartete Farbe fehlt?"},
  {"id":"158","n":"Impuls und Antwort","t":"Linie","nb":["Zeit & Körper"],"v":0,"s":0,"d":12,"a":"Setze ohne Vorzeichnung eine erste Spur. Betrachte sie kurz und füge nur eine zweite Spur hinzu, die auf die erste reagiert. Wiederhole diesen Wechsel zehnmal.","m":"Papier, Farb- oder Zeichenmittel","f":"Ab welchem Schritt hattest du das Gefühl, eher zu antworten als zu planen?"},
  {"id":"159","n":"Schnelles Blatt wird Ausgangsmaterial","t":"Zufall","nb":["Farbe","Form"],"v":0,"s":0,"d":12,"a":"Erzeuge in zwei Minuten eine ungeplante Farbfläche. Schneide danach einen interessanten Bereich heraus und entwickle nur diesen langsam weiter.","m":"Papier, Farbe, grober Pinsel, Schere","f":"Was unterscheidet das langsame Bild vom schnellen, und was ist gleich geblieben?"},
  {"id":"160","n":"Ein Symbol – drei Kontexte","t":"Symbol & Würdigung","nb":["Form"],"v":0,"s":1,"d":15,"a":"Wähle ein einfaches Symbol oder Zeichen und setze es in drei völlig verschiedene bildnerische Umgebungen. Die Form des Symbols bleibt gleich.","m":"Papier, Zeichen-/Collagematerial","f":"Wie stark verändert der Kontext das gleiche Zeichen?"},
  {"id":"161","n":"Zufallslinie wird Maß","t":"Zufall","nb":["Form","Linie"],"v":0,"s":1,"d":15,"a":"Lass eine Schnur aus geringer Höhe auf Papier fallen, zeichne ihre Lage nach und verwende diese zufällige Kurve anschließend als wiederkehrendes Maß oder Raster für eine Komposition.","m":"Schnur, Papier, Stift","f":"Was geschieht, wenn Zufall nachträglich zur Regel wird?"},
  {"id":"162","n":"Weich wird konstruktiv","t":"Raum & Material","nb":["Form"],"v":0,"s":1,"d":15,"a":"Nimm ein weiches oder flexibles Material und versuche, daraus eine möglichst klare, stabile geometrische Form zu erzeugen – ohne das Material dauerhaft zu verhärten.","m":"Stoff, Filz, Schnur, Papier o. Ä.","f":"Welche Eigenschaft des Materials arbeitet gegen deine gewünschte Form?"},
  {"id":"163","n":"Erste Entscheidung gilt","t":"Zufall","nb":["Farbe","Zeit & Körper"],"v":0,"s":0,"d":8,"a":"Wähle ohne langes Abwägen eine Farbe und ein Werkzeug. Arbeite fünf Minuten ausschließlich damit; erst danach darfst du wechseln.","m":"Farbe/Zeichenmittel","f":"Was wurde durch die frühe Entscheidung möglich – und was ausgeschlossen?"},
  {"id":"164","n":"Zwei-Minuten-Regel","t":"Zufall","nb":["Farbe","Zeit & Körper"],"v":0,"s":0,"d":2,"a":"Lege für ein Blatt genau zwei Minuten fest. Innerhalb dieser Zeit entscheidest du schnell über Farbe, Richtung und Fläche; danach bleibt das Blatt unangetastet.","m":"Papier, flüssige Farbe, grobes Werkzeug","f":"Welche Entscheidung fiel nur deshalb, weil keine Zeit zum Abwägen blieb?"},
  {"id":"165","n":"Figur folgt Interesse","t":"Form","nb":["Raum & Material"],"v":0,"s":1,"d":12,"a":"Lege zehn kleine Formen locker auf eine Fläche. Entscheide, welche eine Figur werden soll, und verändere nur Hintergrund, Abstand und Nachbarschaft – nicht die Figur selbst.","m":"Papierformen oder digitale Formen","f":"Welche Veränderung des Grundes macht dieselbe Figur wichtiger?"},
  {"id":"166","n":"Zufallsmaß anwenden","t":"Zufall","nb":["Form","Linie"],"v":0,"s":1,"d":15,"a":"Erzeuge drei zufällige Kurven mit Schnur. Wähle eine davon als 'Lineal' und benutze sie mindestens fünfmal in derselben Komposition.","m":"Schnur, Papier, Stift","f":"Wann wird die zufällige Form durch Wiederholung zu einer Ordnung?"},
  {"id":"167","n":"Fünf Bewegungsqualitäten als Linien","t":"Linie","nb":["Symbol & Würdigung","Zeit & Körper"],"v":0,"s":0,"d":12,"a":"Definiere fünf deutlich unterschiedliche Bewegungsqualitäten, z. B. fließend, kantig, wirbelnd, leicht, still. Lege für jede eine eigene Linienregel fest.","m":"Papier, Stifte","f":"Welche Linienregel ist am eindeutigsten, ohne etwas darzustellen?"},
  {"id":"168","n":"Nicht für ein Publikum","t":"Symbol & Würdigung","nb":["Zufall"],"v":0,"s":0,"d":12,"a":"Sage dir vor dem Start: Diese Arbeit muss weder gezeigt noch erklärt noch bewertet werden. Arbeite dann mit beliebigem Material und frage dich bei jedem Schritt nur: Was ist der nächste sinnvolle gestalterische Schritt für diese Arbeit?","m":"beliebiges Material","f":"Welche Entscheidung hättest du anders getroffen, wenn du an ein Publikum gedacht hättest?"},
  {"id":"169","n":"Serienmalen 5 × 2 Minuten","t":"Zeit & Körper","nb":["Farbe"],"v":0,"s":0,"d":14,"a":"Lege fünf Blätter bereit. Male jedes genau zwei Minuten ohne Themenvorgabe; wechsle unmittelbar zum nächsten Blatt. Verwende grobe Werkzeuge und arbeite möglichst im Stehen.","m":"5 Blätter, flüssige Farbe, grobe Pinsel/Spachtel","f":"Gibt es formale Gewohnheiten, die in allen Blättern wiederkehren? Welche?"},
  {"id":"170","n":"Malen ohne Motivvorgabe","t":"Zufall","nb":["Linie","Zeit & Körper"],"v":0,"s":0,"d":15,"a":"Beginne mit einer Farbe oder Spur, die dich spontan interessiert. Lass jeden nächsten Schritt aus dem gerade Sichtbaren entstehen, ohne vorher ein Motiv festzulegen.","m":"Papier/Leinwand, Farbe","f":"Wann hat das Bild begonnen, dir den nächsten Schritt vorzuschlagen?"},
  {"id":"171","n":"Spur ohne Kommentar","t":"Linie","nb":["Symbol & Würdigung","Zeit & Körper"],"v":0,"s":0,"d":12,"a":"Arbeite zehn Minuten mit Farbe oder Stift. Währenddessen und direkt danach gibst du der Arbeit keinen Titel und erklärst nichts. Erst später darf sie beschrieben werden.","m":"Papier, Farb-/Zeichenmittel","f":"Was bemerkst du, wenn du die Arbeit zunächst nicht erklären musst?"},
  {"id":"172","n":"Dauerblick – eine Spur","t":"Zeit & Körper","nb":["Linie"],"v":0,"s":0,"d":6,"a":"Betrachte fünf Minuten lang einen einfachen Gegenstand oder eine ruhige Szene. Setze nur alle 30 Sekunden eine einzige Linie oder Markierung auf das Blatt.","m":"Objekt/Szene, Papier, Stift","f":"Was verändert sich am Sehen, wenn die Hand viel seltener handeln darf?"},
  {"id":"173","n":"Bewegung wird Spur","t":"Linie","nb":["Zeit & Körper"],"v":0,"s":0,"d":12,"a":"Bewege dich nacheinander in fünf selbstgewählten Qualitäten, z. B. weich, kantig, ungeordnet, leicht, sehr langsam. Übertrage jede direkt anschließend in eine einminütige Zeichnung.","m":"Bewegungsraum, Papier, Stift","f":"Welche Spur erinnert am stärksten an die Bewegung, ohne sie abzubilden?"},
  {"id":"174","n":"Denken als Diagramm","t":"Raum & Material","nb":["Linie","Symbol & Würdigung"],"v":0,"s":0,"d":8,"a":"Nimm einen einfachen Gedanken oder Ablauf und zeichne ihn fünf Minuten lang nur mit Pfeilen, Kreisen, Linien, Wörtern und Verbindungen auf eine große Fläche.","m":"großes Papier/Whiteboard, Stift/Kreide","f":"Hat das Zeichnen dein Denken verändert? Wie?"},
  {"id":"175","n":"Sehen oder deuten?","t":"Symbol & Würdigung","nb":[],"v":1,"s":0,"d":6,"a":"Schreibe sechs Sätze über deine Arbeit. Markiere danach jeden Satz als 'sichtbare Beobachtung' oder 'Deutung/Assoziation'.","m":"eigene Arbeit, Papier","f":"Welche Deutung hattest du zunächst für eine Beobachtung gehalten?"},
  {"id":"176","n":"Farbwirkung prüfen","t":"Farbe","nb":["Symbol & Würdigung"],"v":1,"s":1,"d":7,"a":"Notiere spontan, welche Wirkung zwei dominante Farben für dich haben. Suche anschließend drei rein formale Gründe, die dieselbe Wirkung mitverursachen könnten: Menge, Helligkeit, Nachbarschaft, Position.","m":"eigene Arbeit","f":"Was kommt wirklich von der Farbe – und was von ihrem Kontext?"},
  {"id":"177","n":"Symbol offen halten","t":"Symbol & Würdigung","nb":[],"v":1,"s":1,"d":6,"a":"Wähle ein auffälliges Zeichen deiner Arbeit und formuliere drei verschiedene mögliche Bedeutungen, ohne eine davon zur 'richtigen' zu erklären.","m":"eigene Arbeit","f":"Welche Lesart verändert deine Wahrnehmung der Form am stärksten?"},
  {"id":"178","n":"Figur wechselt","t":"Form","nb":["Symbol & Würdigung","Zeit & Körper"],"v":1,"s":0,"d":5,"a":"Betrachte die Arbeit und benenne zuerst das dominanteste Element. Bleib zwei Minuten dabei und suche dann bewusst ein anderes Element, das zur neuen Figur werden kann.","m":"eigene Arbeit","f":"Was musste in den Hintergrund treten, damit etwas anderes Figur werden konnte?"},
  {"id":"179","n":"Drei Minuten Präsenz","t":"Zeit & Körper","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":5,"a":"Sitze drei Minuten vor deiner fertigen Arbeit, ohne sie zu verändern, zu fotografieren oder zu benennen. Notiere erst danach drei neue Beobachtungen.","m":"eigene Arbeit, Timer","f":"Welche Beobachtung brauchte Zeit, bevor sie auftauchte?"},
  {"id":"180","n":"Zufall oder Entscheidung?","t":"Zufall","nb":["Symbol & Würdigung"],"v":1,"s":0,"d":6,"a":"Markiere gedanklich fünf auffällige Stellen deiner Arbeit und ordne jede einer Skala zu: eher Zufall – Mischform – eher bewusste Entscheidung.","m":"eigene Arbeit","f":"An welcher Stelle wurde ein Zufall erst durch dein Behalten zur Gestaltung?"}
];
